// ============================================================
// PURIFIER FILTER LIFETIME
// ============================================================

/*
 * TEST MODE
 *
 * Choose ONE:
 *
 * 1. 10 minutes
 * 2. 1 hour
 * 3. 4 months
 */

// #define PURIFIER_TEST_10_MIN
// #define PURIFIER_TEST_1_HOUR

#define PURIFIER_TEST_10_MIN

// ============================================================
// FILTER LIFETIME IN SECONDS
// ============================================================

#if defined(PURIFIER_TEST_10_MIN)

    #define PURIFIER_FILTER_LIFETIME_SECONDS \
        (10LL * 60LL)

#elif defined(PURIFIER_TEST_1_HOUR)

    #define PURIFIER_FILTER_LIFETIME_SECONDS \
        (60LL * 60LL)

#elif defined(PURIFIER_PRODUCTION_4_MONTHS)

    /*
     * Approximation:
     *
     * 4 months × 30 days × 24 hours × 60 minutes × 60 sec
     *
     * = 10,368,000 seconds
     */
    #define PURIFIER_FILTER_LIFETIME_SECONDS \
        (4LL * 30LL * 24LL * 60LL * 60LL)

#else

    #error "Select purifier filter lifetime mode"

#endif

// Approximate lifetime used for percentage calculation.
// 4 months × 30.4375 days/month.
// #define PURIFIER_FILTER_LIFETIME_DAYS     (\) /*While uncommenting this line also remove \ from bracket*/ 
//     (PURIFIER_FILTER_LIFETIME_MONTHS * 30.4375)

