static void build_year_list(void)
{
    year_list[0]=0;

    char tmp[8];

    for(int y=1901;y<=2026;y++)
    {
        sprintf(tmp,"%d",y);
        strcat(year_list,tmp);

        if(y!=2026)
            strcat(year_list,"\n");
    }
}

static void theme_switch_cb(lv_event_t *e) {
    lv_obj_t *sw = lv_event_get_target(e);
    is_light_theme = lv_obj_has_state(sw, LV_STATE_CHECKED);

    lv_color_t bg_col   = is_light_theme ? COLOR_LIGHT_BG   : COLOR_BG;
    lv_color_t text_col = is_light_theme ? COLOR_LIGHT_TEXT : COLOR_TEXT;

    // Apply active screen background
    lv_obj_set_style_bg_color(lv_scr_act(), bg_col, 0);

    // Save choice to NVS (add helper in settings_nvs.c if needed)
    // settings_save_theme_preference(is_light_theme);

    show_toast(is_light_theme ? "White Theme Applied" : "Dark Theme Applied", 
               COLOR_OPRUSS_ORG, lv_color_white());
    
    ESP_LOGI("UI", "Theme switched to: %s", is_light_theme ? "LIGHT" : "DARK");
}

// ============================================================
// TIMER POPUP - ADD UNIVERSAL CLOSE BUTTON
// ============================================================

static void add_timer_popup_close_button(
    lv_obj_t *popup)
{
    if (popup == NULL)
        return;

    /*
     * --------------------------------------------------------
     * CREATE X BUTTON
     * --------------------------------------------------------
     */

    lv_obj_t *close_btn =
        lv_btn_create(popup);

    if (close_btn == NULL)
    {
        ESP_LOGE(
            "UI",
            "Failed to create timer popup close button"
        );

        return;
    }

    /*
     * --------------------------------------------------------
     * SIZE
     * --------------------------------------------------------
     */

    lv_obj_set_size(
        close_btn,
        42,
        42
    );

    /*
     * --------------------------------------------------------
     * POSITION
     *
     * Top-right corner of popup.
     *
     * -10 = 10 px from right
     * +10 = 10 px from top
     * --------------------------------------------------------
     */

    lv_obj_align(
        close_btn,
        LV_ALIGN_TOP_RIGHT,
        -10,
        10
    );

    /*
     * --------------------------------------------------------
     * STYLE
     * --------------------------------------------------------
     */

    lv_obj_set_style_bg_color(
        close_btn,
        COLOR_POOR,
        0
    );

    lv_obj_set_style_bg_opa(
        close_btn,
        LV_OPA_COVER,
        0
    );

    lv_obj_set_style_radius(
        close_btn,
        10,
        0
    );

    lv_obj_set_style_border_width(
        close_btn,
        0,
        0
    );

    lv_obj_set_style_shadow_width(
        close_btn,
        0,
        0
    );

    /*
     * --------------------------------------------------------
     * CLICK CALLBACK
     *
     * Pass the popup itself as user data.
     * --------------------------------------------------------
     */

    lv_obj_add_event_cb(
        close_btn,
        timer_popup_close_cb,
        LV_EVENT_CLICKED,
        popup
    );

    /*
     * --------------------------------------------------------
     * X LABEL
     * --------------------------------------------------------
     */

    lv_obj_t *close_lbl =
        lv_label_create(close_btn);

    if (close_lbl == NULL)
        return;

    lv_label_set_text(
        close_lbl,
        LV_SYMBOL_CLOSE
    );

    lv_obj_set_style_text_color(
        close_lbl,
        COLOR_TEXT,
        0
    );

    lv_obj_set_style_text_font(
        close_lbl,
        &lv_font_montserrat_20,
        0
    );

    lv_obj_center(
        close_lbl
    );
}

// ============================================================
// TIMER POPUP - CLOSE CALLBACK
// ============================================================

static void timer_popup_close_cb(lv_event_t *e)
{
    if (e == NULL)
        return;

    /*
     * The popup pointer was passed as user_data
     * when the X button was created.
     */
    lv_obj_t *popup =
        (lv_obj_t *)lv_event_get_user_data(e);

    if (popup == NULL)
        return;

    /*
     * --------------------------------------------------------
     * SLEEP TIMER POPUP
     * --------------------------------------------------------
     */

    if (popup == sleep_time_modal)
    {
        lv_obj_del(
            sleep_time_modal
        );

        sleep_time_modal = NULL;

        ESP_LOGI(
            "UI",
            "Sleep timer popup closed"
        );

        return;
    }

    /*
     * --------------------------------------------------------
     * SLEEP-OFF / SCHEDULE POPUP
     * --------------------------------------------------------
     */

    if (popup == sleep_off_time_modal)
    {
        lv_obj_del(
            sleep_off_time_modal
        );

        sleep_off_time_modal = NULL;

        ESP_LOGI(
            "UI",
            "Sleep schedule popup closed"
        );

        return;
    }

    /*
     * --------------------------------------------------------
     * CALENDAR POPUP
     * --------------------------------------------------------
     */

    if (popup == calendar_modal)
    {
        lv_obj_del(
            calendar_modal
        );

        calendar_modal = NULL;

        /*
         * These objects belong to the calendar popup.
         * They must not be used after the popup is deleted.
         */
        calendar_obj = NULL;
        calendar_title = NULL;
        month_dd = NULL;
        year_dd = NULL;

        ESP_LOGI(
            "UI",
            "Calendar popup closed"
        );

        return;
    }

    /*
     * --------------------------------------------------------
     * FALLBACK
     * --------------------------------------------------------
     *
     * If another Timer popup is added later and isn't
     * explicitly handled above, at least close it.
     * --------------------------------------------------------
     */

    lv_obj_del(popup);

    ESP_LOGI(
        "UI",
        "Timer popup closed"
    );
}


