void ui_restore_purifier_state(
    bool state,
    int filter_life)
{
    purifier_state = state;

    /*
     * Keep the supplied value as a fallback.
     *
     * The actual filter percentage will subsequently be
     * calculated from the stored installation timestamp.
     */
    persisted_filter_life = filter_life;

    if (persisted_filter_life < 0)
        persisted_filter_life = 0;

    if (persisted_filter_life > 100)
        persisted_filter_life = 100;

    ESP_LOGI(
        TAG,
        "Purifier state restored: %s",
        purifier_state ? "ON" : "OFF"
    );

    ESP_LOGI(
        TAG,
        "Fallback filter life: %d%%",
        persisted_filter_life
    );
}

// ============================================================
// PURIFIER NVS FUNCTIONS
// ============================================================

/**
 * Save purifier state and filter installation timestamp.
 */
static esp_err_t purifier_save_state(void)
{
    nvs_handle_t nvs;
    esp_err_t err;

    err = nvs_open(PURIFIER_NVS_NAMESPACE,
                   NVS_READWRITE,
                   &nvs);

    if (err != ESP_OK)
    {
        ESP_LOGE(TAG,
                 "Failed to open purifier NVS: %s",
                 esp_err_to_name(err));

        return err;
    }

    err = nvs_set_u8(
        nvs,
        PURIFIER_NVS_STATE_KEY,
        purifier_state ? 1 : 0
    );

    if (err != ESP_OK)
    {
        ESP_LOGE(TAG,
                 "Failed to save purifier state: %s",
                 esp_err_to_name(err));

        nvs_close(nvs);
        return err;
    }

    err = nvs_set_i64(
        nvs,
        PURIFIER_NVS_INSTALL_TIME_KEY,
        (int64_t)purifier_install_time
    );

    if (err != ESP_OK)
    {
        ESP_LOGE(TAG,
                 "Failed to save purifier installation time: %s",
                 esp_err_to_name(err));

        nvs_close(nvs);
        return err;
    }

    err = nvs_set_u8(
        nvs,
        PURIFIER_NVS_FILTER_KEY,
        (uint8_t)persisted_filter_life
    );

    if (err != ESP_OK)
    {
        ESP_LOGE(TAG,
                 "Failed to save purifier filter life: %s",
                 esp_err_to_name(err));

        nvs_close(nvs);
        return err;
    }

    err = nvs_commit(nvs);

    if (err != ESP_OK)
    {
        ESP_LOGE(TAG,
                 "Failed to commit purifier NVS: %s",
                 esp_err_to_name(err));
    }

    nvs_close(nvs);

    return err;
}

/**
 * Restore purifier configuration from NVS.
 *
 * If no installation timestamp exists, the filter is treated
 * as a new filter and the current time is stored.
 */
static void purifier_load_state(void)
{
    nvs_handle_t nvs;

    esp_err_t err = nvs_open(
        PURIFIER_NVS_NAMESPACE,
        NVS_READWRITE,
        &nvs
    );

    if (err != ESP_OK)
    {
        ESP_LOGE(TAG,
                 "Failed to open purifier NVS: %s",
                 esp_err_to_name(err));

        return;
    }

    // --------------------------------------------------------
    // Restore ON/OFF state
    // --------------------------------------------------------

    uint8_t state = 1;

    err = nvs_get_u8(
        nvs,
        PURIFIER_NVS_STATE_KEY,
        &state
    );

    if (err == ESP_OK)
    {
        purifier_state = (state != 0);
    }
    else if (err == ESP_ERR_NVS_NOT_FOUND)
    {
        purifier_state = true;

        nvs_set_u8(
            nvs,
            PURIFIER_NVS_STATE_KEY,
            1
        );
    }

    // --------------------------------------------------------
    // Restore installation timestamp
    // --------------------------------------------------------

    int64_t stored_install_time = 0;

    err = nvs_get_i64(
        nvs,
        PURIFIER_NVS_INSTALL_TIME_KEY,
        &stored_install_time
    );

    if (err == ESP_OK &&
        stored_install_time > 0)
    {
        purifier_install_time =
            (time_t)stored_install_time;

        ESP_LOGI(
            TAG,
            "Purifier installed at: %lld",
            (long long)purifier_install_time
        );
    }
    else
    {
        /*
        * No authorized installation has happened yet.
        *
        * IMPORTANT:
        * Do NOT start the 4-month timer automatically.
        */
        purifier_install_time = 0;

        persisted_filter_life = 100;

        ESP_LOGI(
            TAG,
            "Purifier not commissioned yet"
        );
    }

    // --------------------------------------------------------
    // Restore previous calculated percentage
    // --------------------------------------------------------

    uint8_t stored_filter = 100;

    err = nvs_get_u8(
        nvs,
        PURIFIER_NVS_FILTER_KEY,
        &stored_filter
    );

    if (err == ESP_OK)
    {
        persisted_filter_life = stored_filter;
    }
    else
    {
        persisted_filter_life = 100;
    }

    // Clamp
    if (persisted_filter_life < 0)
        persisted_filter_life = 0;

    if (persisted_filter_life > 100)
        persisted_filter_life = 100;

    nvs_commit(nvs);

    nvs_close(nvs);

    ESP_LOGI(
        TAG,
        "Purifier restored: state=%s filter=%d%% install_time=%lld",
        purifier_state ? "ON" : "OFF",
        persisted_filter_life,
        (long long)purifier_install_time
    );
}

// ============================================================
// CALCULATE FILTER LIFE
// ============================================================

static int purifier_calculate_filter_life(void)
{
    /*
     * If installation time is not available yet,
     * keep the last known value.
     */
    if (purifier_install_time <= 0)
    {
        return persisted_filter_life;
    }

    time_t now = time(NULL);

    /*
     * System clock has not been synchronized.
     */
    if (now <= 1000000000)
    {
        return persisted_filter_life;
    }

    /*
     * Prevent negative elapsed time.
     */
    if (now < purifier_install_time)
    {
        return 100;
    }

    double elapsed_seconds =
        difftime(now, purifier_install_time);

    double elapsed_days =
        elapsed_seconds / 86400.0;

    /*
     * 4 months ≈ 121.75 days.
     */
    double lifetime_days =
        PURIFIER_FILTER_LIFETIME_SECONDS;
        // PURIFIER_TEST_10_MIN;

    double remaining =
        100.0 *
        (1.0 - (elapsed_days / lifetime_days));

    int filter_life =
        (int)(remaining + 0.5);

    if (filter_life < 0)
        filter_life = 0;

    if (filter_life > 100)
        filter_life = 100;

    return filter_life;
}

