// ============================================================
// CLOSE PURIFIER PASSWORD MODAL
// ============================================================
static void purifier_replace_close_cb(lv_event_t *e)
{
    LV_UNUSED(e);

    ESP_LOGI(
        "PURIFIER",
        "Closing purifier password popup"
    );

    // --------------------------------------------------------
    // Delete keyboard
    // --------------------------------------------------------

    if (purifier_password_kb != NULL)
    {
        lv_keyboard_set_textarea(
            purifier_password_kb,
            NULL
        );

        lv_obj_del(
            purifier_password_kb
        );

        purifier_password_kb = NULL;
    }

    // --------------------------------------------------------
    // Delete keyboard X button
    // --------------------------------------------------------

    if (purifier_keyboard_close_btn != NULL)
    {
        lv_obj_del(
            purifier_keyboard_close_btn
        );

        purifier_keyboard_close_btn = NULL;
    }

    if (purifier_replace_modal != NULL)
    {
        /*
         * Delete the parent.
         *
         * This automatically deletes:
         * - password textarea
         * - keyboard
         * - buttons
         * - labels
         */
        lv_obj_del(
            purifier_replace_modal
        );

        purifier_replace_modal = NULL;
    }

    /*
     * These are child pointers.
     * They are no longer valid after the parent
     * has been deleted, so clear them.
     */
    purifier_password_ta = NULL;

}

// ============================================================
// VERIFY PURIFIER REPLACEMENT PASSWORD
// ============================================================

static void purifier_replace_confirm_cb(lv_event_t *e)
{
    // ========================================================
    // SAFETY CHECK
    // ========================================================

    if (e == NULL)
    {
        ESP_LOGE(
            "PURIFIER",
            "Confirm callback received NULL event"
        );

        return;
    }

    ESP_LOGI(
        "PURIFIER",
        "Filter replacement tick button pressed"
    );

    // ========================================================
    // GET PASSWORD TEXTAREA
    // ========================================================

    lv_obj_t *password_ta =
        (lv_obj_t *)lv_event_get_user_data(e);

    if (password_ta == NULL)
    {
        ESP_LOGE(
            "PURIFIER",
            "Password textarea is NULL"
        );

        show_toast(
            "Password field error",
            COLOR_POOR,
            COLOR_TEXT
        );

        return;
    }

    // ========================================================
    // READ PASSWORD
    // ========================================================

    const char *entered_password =
        lv_textarea_get_text(
            password_ta
        );

    if (entered_password == NULL)
    {
        ESP_LOGE(
            "PURIFIER",
            "Password text is NULL"
        );

        return;
    }

    ESP_LOGI(
        "PURIFIER",
        "Password entered, length=%d",
        (int)strlen(entered_password)
    );

    // ========================================================
    // EMPTY PASSWORD
    // ========================================================

    if (strlen(entered_password) == 0)
    {
        show_toast(
            "Enter password",
            COLOR_POOR,
            COLOR_TEXT
        );

        return;
    }

    // ========================================================
    // VERIFY PASSWORD
    // ========================================================

    if (strcmp(
            entered_password,
            PURIFIER_PASSWORD
        ) != 0)
    {
        ESP_LOGW(
            "PURIFIER",
            "Invalid purifier installation password"
        );

        show_toast(
            "Invalid password",
            COLOR_POOR,
            COLOR_TEXT
        );

        /*
         * Clear password so the installer must
         * enter it again.
         */
        lv_textarea_set_text(
            password_ta,
            ""
        );

        return;
    }

    // ========================================================
    // PASSWORD CORRECT
    // ========================================================

    ESP_LOGI(
        "PURIFIER",
        "Purifier installation password accepted"
    );

    // ========================================================
    // START / RESET FILTER LIFETIME
    // ========================================================

    if (!purifier_start_new_filter())
    {
        ESP_LOGE(
            "PURIFIER",
            "Failed to start new filter lifetime"
        );

        show_toast(
            "Filter installation failed",
            COLOR_POOR,
            COLOR_TEXT
        );

        return;
    }

    ESP_LOGI(
        "PURIFIER",
        "Filter installation successful"
    );

    // ========================================================
    // CLOSE KEYBOARD
    // ========================================================

    if (purifier_password_kb != NULL)
    {
        lv_keyboard_set_textarea(
            purifier_password_kb,
            NULL
        );

        lv_obj_del(
            purifier_password_kb
        );

        purifier_password_kb = NULL;
    }

    // ========================================================
    // CLOSE KEYBOARD X BUTTON
    // ========================================================

    if (purifier_keyboard_close_btn != NULL)
    {
        lv_obj_del(
            purifier_keyboard_close_btn
        );

        purifier_keyboard_close_btn = NULL;
    }

    // ========================================================
    // CLOSE PASSWORD POPUP
    // ========================================================

    if (purifier_replace_modal != NULL)
    {
        lv_obj_del(
            purifier_replace_modal
        );

        purifier_replace_modal = NULL;
    }

    purifier_password_ta = NULL;

    // ========================================================
    // UPDATE SCREEN 1
    // ========================================================

    if (purifier_filter_lbl != NULL)
    {
        lv_label_set_text(
            purifier_filter_lbl,
            "Filter 100%"
        );

        lv_obj_set_style_text_color(
            purifier_filter_lbl,
            COLOR_TEXT,
            0
        );
    }

    if (purifier_status_lbl != NULL)
    {
        lv_label_set_text(
            purifier_status_lbl,
            purifier_state
                ? "ON"
                : "OFF"
        );

        lv_obj_set_style_text_color(
            purifier_status_lbl,
            purifier_state
                ? COLOR_EXCELLENT
                : COLOR_TEXT,
            0
        );
    }

    show_toast(
        "Filter installed",
        COLOR_EXCELLENT,
        COLOR_TEXT
    );
}

