// Background scan task
static void wifi_scan_task(void *pv) {
    wifi_scan_config_t scan_config = {
        .ssid = NULL, .bssid = NULL, .channel = 0,
        .show_hidden = false,
        .scan_type = WIFI_SCAN_TYPE_ACTIVE,
        .scan_time.active.min = 50, .scan_time.active.max = 200,
    };

    ESP_LOGI(
        "WIFI",
        "Starting WiFi scan without disconnecting"
    );

    esp_err_t ret =
        esp_wifi_scan_start(
            &scan_config,
            true
        );

    if (ret != ESP_OK)
    {
        ESP_LOGE(
            "WIFI",
            "WiFi scan failed: %s",
            esp_err_to_name(ret)
        );

        lv_async_call(
            wifi_scan_complete_cb,
            NULL
        );

        vTaskDelete(NULL);
        return;
    }
    
    uint16_t ap_count = 0;
    ret = esp_wifi_scan_get_ap_num(&ap_count);
    
    if (ret != ESP_OK)
    {
        ESP_LOGE(
            "WIFI",
            "Failed to get AP count: %s",
            esp_err_to_name(ret)
        );

        lv_async_call(
            wifi_scan_complete_cb,
            NULL
        );

        vTaskDelete(NULL);
        return;
    }

    ESP_LOGI(
        "WIFI",
        "Raw scan result count: %u",
        ap_count
    );

    // Allocate memory for results
    wifi_ap_record_t *ap_records = NULL;
    if (ap_count > 0) {
        ap_records = malloc(ap_count * sizeof(wifi_ap_record_t));
        if (ap_records == NULL)
        {
            ESP_LOGE(
                "WIFI",
                "Failed to allocate scan results"
            );

            lv_async_call(
                wifi_scan_complete_cb,
                NULL
            );

            vTaskDelete(NULL);
            return;
        }
        ret = esp_wifi_scan_get_ap_records(
            &ap_count,
            ap_records
        );

        if (ret != ESP_OK)
        {
            ESP_LOGE(
                "WIFI",
                "Failed to get AP records: %s",
                esp_err_to_name(ret)
            );

            free(ap_records);

            lv_async_call(
                wifi_scan_complete_cb,
                NULL
            );

            vTaskDelete(NULL);
            return;
        }
    }
    
    // Store results for main thread
    wifi_scan_result_t *result = malloc(sizeof(wifi_scan_result_t));
    if (result == NULL)
    {
        ESP_LOGE(
            "WIFI",
            "Failed to allocate scan result"
        );

        free(ap_records);

        vTaskDelete(NULL);
        return;
    }
        result->count = ap_count;
        result->records = ap_records;
        lv_async_call(wifi_scan_complete_cb, result);
    
    
    vTaskDelete(NULL);
}

// Callback on main LVGL thread
static void wifi_scan_complete_cb(void *data)
{
    wifi_scan_result_t *result =
        (wifi_scan_result_t *)data;

    if (wifi_list)
    {
        lv_obj_clean(wifi_list);
    }

    if (result == NULL)
    {
        if (wifi_status_label)
        {
            lv_label_set_text(
                wifi_status_label,
                "Scan failed"
            );
        }

        return;
    }

    if (result->count == 0 ||
        result->records == NULL)
    {
        if (wifi_status_label)
        {
            lv_label_set_text(
                wifi_status_label,
                "No networks found"
            );
        }

        free(result);

        return;
    }


    /*
     * ========================================================
     * REMOVE DUPLICATE SSIDs
     * ========================================================
     *
     * One physical network can appear multiple times because
     * of multiple BSSIDs / access points / bands.
     *
     * We show only ONE entry per SSID.
     */

    int unique_count = 0;


    for (int i = 0;
         i < result->count;
         i++)
    {
        char *current_ssid =
            (char *)result->records[i].ssid;


        /*
         * Ignore empty SSIDs.
         */
        if (current_ssid[0] == '\0')
        {
            continue;
        }


        /*
         * Check whether this SSID was already displayed.
         */
        bool duplicate = false;

        for (int j = 0;
             j < i;
             j++)
        {
            char *previous_ssid =
                (char *)result->records[j].ssid;

            if (previous_ssid[0] == '\0')
            {
                continue;
            }

            if (strcmp(
                    current_ssid,
                    previous_ssid
                ) == 0)
            {
                duplicate = true;
                break;
            }
        }


        if (duplicate)
        {
            continue;
        }


        /*
         * Find the strongest AP for this SSID.
         *
         * If the same SSID appears multiple times,
         * show the strongest RSSI.
         */

        int strongest_rssi =
            result->records[i].rssi;


        for (int j = i + 1;
             j < result->count;
             j++)
        {
            if (strcmp(
                    current_ssid,
                    (char *)result->records[j].ssid
                ) == 0)
            {
                if (result->records[j].rssi >
                    strongest_rssi)
                {
                    strongest_rssi =
                        result->records[j].rssi;
                }
            }
        }


        /*
         * Display only one button.
         */

        char ssid_display[96];

        snprintf(
            ssid_display,
            sizeof(ssid_display),
            "%s  (%d dBm)",
            current_ssid,
            strongest_rssi
        );


        if (wifi_list)
        {
            lv_obj_t *btn =
                lv_list_add_btn(
                    wifi_list,
                    LV_SYMBOL_WIFI,
                    ssid_display
                );

            if (btn)
            {
                char *ssid_copy =
                    strdup(current_ssid);

                if (ssid_copy)
                {
                    lv_obj_set_user_data(
                        btn,
                        ssid_copy
                    );

                    lv_obj_add_event_cb(
                        btn,
                        wifi_network_selected_cb,
                        LV_EVENT_CLICKED,
                        NULL
                    );
                }
            }
        }

        unique_count++;
    }


    ESP_LOGI(
        "WIFI",
        "WiFi scan: %u raw APs -> %d unique networks",
        result->count,
        unique_count
    );


    if (wifi_status_label)
    {
        lv_label_set_text_fmt(
            wifi_status_label,
            "Found %d networks",
            unique_count
        );
    }


    free(result->records);
    free(result);
}

static void sleep_mode_switch_cb(lv_event_t *e)
{
    lv_obj_t *sw = lv_event_get_target(e);

    if (sw == NULL)
        return;

    bool schedule_mode =
        lv_obj_has_state(sw, LV_STATE_CHECKED);

    sleep_schedule_mode = schedule_mode;

    if (sleep_mode_label == NULL ||
        sleep_timer_container == NULL ||
        sleep_schedule_container == NULL)
    {
        ESP_LOGE(
            TAG,
            "Sleep UI objects are NULL"
        );
        return;
    }

    if (schedule_mode)
    {
        // -----------------------------------------
        // SCHEDULE MODE
        // -----------------------------------------

        lv_label_set_text(
            sleep_mode_label,
            "Schedule"
        );

        lv_obj_add_flag(
            sleep_timer_container,
            LV_OBJ_FLAG_HIDDEN
        );

        lv_obj_clear_flag(
            sleep_schedule_container,
            LV_OBJ_FLAG_HIDDEN
        );
    }
    else
    {
        // -----------------------------------------
        // TIMER MODE
        // -----------------------------------------

        lv_label_set_text(
            sleep_mode_label,
            "Timer"
        );

        lv_obj_clear_flag(
            sleep_timer_container,
            LV_OBJ_FLAG_HIDDEN
        );

        lv_obj_add_flag(
            sleep_schedule_container,
            LV_OBJ_FLAG_HIDDEN
        );
    }
}

