static void sleep_time_done_cb(lv_event_t *e)
{
    LV_UNUSED(e);

    if (!sleep_time_modal)
        return;

    lv_obj_t *hour_roller =
        lv_obj_get_user_data(
            sleep_time_modal
        );

    if (!hour_roller)
        return;

    lv_obj_t *minute_roller =
        lv_obj_get_user_data(
            hour_roller
        );

    if (!minute_roller)
        return;

    sleep_wake_hour =
        lv_roller_get_selected(
            hour_roller
        );

    /*
     * Minute roller options are:
     *
     * 0, 5, 10, 15 ... 55
     *
     * lv_roller_get_selected()
     * returns the INDEX, not the displayed value.
     */
    sleep_wake_minute =
        lv_roller_get_selected(
            minute_roller
        ) * 5;

    /*
     * --------------------------------------------------------
     * Make sure a date has already been selected.
     * --------------------------------------------------------
     */
    if (sleep_wake_year <= 0 ||
        sleep_wake_month <= 0 ||
        sleep_wake_day <= 0)
    {
        show_toast(
            "Select a date first",
            COLOR_POOR,
            COLOR_TEXT
        );

        return;
    }

    /*
     * --------------------------------------------------------
     * Build selected wake date/time.
     * --------------------------------------------------------
     */
    struct tm wake_tm = {0};

    wake_tm.tm_year =
        sleep_wake_year - 1900;

    wake_tm.tm_mon =
        sleep_wake_month - 1;

    wake_tm.tm_mday =
        sleep_wake_day;

    wake_tm.tm_hour =
        sleep_wake_hour;

    wake_tm.tm_min =
        sleep_wake_minute;

    wake_tm.tm_sec = 0;

    /*
     * Let the C library determine DST correctly.
     */
    wake_tm.tm_isdst = -1;

    time_t wake =
        mktime(&wake_tm);

    if (wake == (time_t)-1)
    {
        show_toast(
            "Invalid wake time",
            COLOR_POOR,
            COLOR_TEXT
        );

        return;
    }

    /*
     * --------------------------------------------------------
     * Compare against CURRENT time.
     * --------------------------------------------------------
     */
    time_t now;
    time(&now);

    if ((uint64_t)wake <= (uint64_t)now)
    {
        show_toast(
            "Wake time must be in the future",
            COLOR_POOR,
            COLOR_TEXT
        );

        return;
    }

    /*
     * --------------------------------------------------------
     * Save absolute wake epoch.
     * --------------------------------------------------------
     */
    sleep_wake_epoch =
        (uint64_t)wake;

    sleep_schedule_set = true;

    /*
     * Update visible label.
     */
    char buf[64];

    snprintf(
        buf,
        sizeof(buf),
        "Wake: %02d/%02d/%04d  %02d:%02d",
        sleep_wake_day,
        sleep_wake_month,
        sleep_wake_year,
        sleep_wake_hour,
        sleep_wake_minute
    );

    if (sleep_time_label)
    {
        lv_label_set_text(
            sleep_time_label,
            buf
        );
    }

    /*
     * Close time picker.
     */
    if (sleep_time_modal != NULL)
    {
        lv_obj_del(sleep_time_modal);
        sleep_time_modal = NULL;
    }
    

    ESP_LOGI(
        TAG,
        "WAKE SCHEDULE SET: %02d/%02d/%04d %02d:%02d epoch=%llu",
        sleep_wake_day,
        sleep_wake_month,
        sleep_wake_year,
        sleep_wake_hour,
        sleep_wake_minute,
        (unsigned long long)sleep_wake_epoch
    );

    /*
     * IMPORTANT:
     *
     * Do NOT turn OFF yet.
     *
     * Ask:
     *   Add OFF Time?
     *   Turn Off Now?
     *   Cancel?
     */
    // sleep_show_on_schedule_confirmation();
}

