static void sleep_off_time_done_cb(lv_event_t *e)
{
    LV_UNUSED(e);

    if (sleep_off_time_modal == NULL)
        return;

    lv_obj_t *hours =
        lv_obj_get_user_data(
            sleep_off_time_modal
        );

    if (hours == NULL)
        return;

    lv_obj_t *minutes =
        lv_obj_get_user_data(hours);

    if (minutes == NULL)
        return;

    sleep_off_hour =
        lv_roller_get_selected(hours);

    /*
     * Roller index:
     *
     * 0 = 00
     * 1 = 05
     * 2 = 10
     * ...
     * 11 = 55
     */
    sleep_off_minute =
        lv_roller_get_selected(minutes) * 5;

    /*
     * Use TODAY for the OFF date.
     */
    time_t now;
    time(&now);

    struct tm now_tm;
    localtime_r(
        &now,
        &now_tm
    );

    struct tm off_tm = {0};

    off_tm.tm_year =
        now_tm.tm_year;

    off_tm.tm_mon =
        now_tm.tm_mon;

    off_tm.tm_mday =
        now_tm.tm_mday;

    off_tm.tm_hour =
        sleep_off_hour;

    off_tm.tm_min =
        sleep_off_minute;

    off_tm.tm_sec = 0;
    off_tm.tm_isdst = -1;

    time_t off_time =
        mktime(&off_tm);

    if (off_time == (time_t)-1)
    {
        show_toast(
            "Invalid OFF time",
            COLOR_POOR,
            lv_color_white()
        );

        return;
    }

    /*
     * OFF TIME MUST BE AFTER CURRENT TIME.
     */
    if (off_time <= now)
    {
        show_toast(
            "OFF time must be in the future",
            COLOR_POOR,
            lv_color_white()
        );

        return;
    }

    /*
     * OFF must happen BEFORE the configured
     * ON / WAKE time.
     */
    if (sleep_wake_epoch != 0 &&
        (uint64_t)off_time >= sleep_wake_epoch)
    {
        show_toast(
            "OFF time must be before ON time",
            COLOR_POOR,
            lv_color_white()
        );

        return;
    }

    sleep_off_epoch =
        (uint64_t)off_time;

    sleep_off_schedule_set = true;

    if (sleep_off_schedule_timer == NULL)
    {
        sleep_off_schedule_timer =
            lv_timer_create(
                sleep_off_schedule_cb,
                1000,
                NULL
            );
    }

    if (sleep_off_time_modal != NULL)
    {
        lv_obj_del(sleep_off_time_modal);
        sleep_off_time_modal = NULL;
    }

    ESP_LOGI(
        TAG,
        "OFF schedule set: %02d:%02d epoch=%llu",
        sleep_off_hour,
        sleep_off_minute,
        (unsigned long long)sleep_off_epoch
    );

    /*
     * The OFF time is now configured.
     * Keep the device ON until that time.
     */
    sleep_schedule_set = true;
}

static void sleep_off_schedule_cb(lv_timer_t *timer)
{
    LV_UNUSED(timer);

    if (!sleep_off_schedule_set)
        return;

    time_t now;
    time(&now);

    if ((uint64_t)now < sleep_off_epoch)
        return;

    /*
     * OFF time reached.
     */
    sleep_off_schedule_set = false;

    ESP_LOGI(
        TAG,
        "OFF schedule reached. Entering OFF state."
    );

    sleep_start_off_state();
}

