static void sleep_save_state(void)
{
    settings_save_sleep_state(
        sleep_timer_active,
        sleep_schedule_mode,
        sleep_wake_epoch,
        0
    );
}

static void sleep_load_state(void)
{
    bool active = false;
    bool schedule = false;

    uint64_t wake_epoch = 0;

    int timer_minutes = 0;

    if (settings_load_sleep_state(
            &active,
            &schedule,
            &wake_epoch,
            &timer_minutes))
    {
        sleep_timer_active = active;
        sleep_schedule_mode = schedule;
        sleep_wake_epoch = wake_epoch;
    }
}

static void sleep_enter_off_state(void)
{
     if (!sleep_schedule_mode)
    {
        if (sleep_timer_deadline_us <= 0)
            return;
    }
    else
    {
        if (sleep_wake_epoch == 0)
            return;
    }
    //------------------------------------------------
    // ACTUAL OFF STATE STARTS HERE
    // --------------------------------------------------------

    sleep_timer_active = true;
    aq7_sensing_enabled = false;

    // --------------------------------------------------------
    // HIDE EVERYTHING RELATED TO SLEEP UI
    // --------------------------------------------------------

    if (sleep_status_label)
    {
        lv_obj_add_flag(
            sleep_status_label,
            LV_OBJ_FLAG_HIDDEN
        );
    }

    if (set_timer_btn)
    {
        lv_obj_add_flag(
            set_timer_btn,
            LV_OBJ_FLAG_HIDDEN
        );
    }

    if (sleep_off_btn)
    {
        lv_obj_add_flag(
            sleep_off_btn,
            LV_OBJ_FLAG_HIDDEN
        );
    }


    // Hide the timer/schedule controls too
    if (sleep_timer_container)
    {
        lv_obj_add_flag(
            sleep_timer_container,
            LV_OBJ_FLAG_HIDDEN
        );
    }

    if (sleep_schedule_container)
    {
        lv_obj_add_flag(
            sleep_schedule_container,
            LV_OBJ_FLAG_HIDDEN
        );
    }

    // Turn LCD/backlight OFF.
    // Wi-Fi/MQTT are deliberately NOT touched.
    // --------------------------------------------------------
    // TURN LCD BACKLIGHT OFF
    // --------------------------------------------------------

    esp_err_t ret =
        wavesahre_rgb_lcd_bl_off();

    // --------------------------------------------------------
    // SAVE OFF STATE
    // --------------------------------------------------------

    

    if (ret != ESP_OK)
    {
        ESP_LOGE(
            TAG,
            "LCD backlight OFF failed: %s",
            esp_err_to_name(ret)
        );
    }
    else
    {
        ESP_LOGI(
            TAG,
            "LCD backlight OFF successful"
        );
    }

    sleep_save_state();

        ESP_LOGI(TAG,
                "AQ7 OFF state entered. Wake epoch=%llu",
                (unsigned long long)sleep_wake_epoch);
    
}

static void sleep_exit_off_state(void)
{
    ESP_LOGW(
        TAG,
        "WAKE DEBUG: sleep_exit_off_state() called, wake_epoch=%llu",
        (unsigned long long)sleep_wake_epoch
    );
    sleep_timer_active = false;

    /*
     * The previous schedule has completed.
     */
    sleep_schedule_set = false;
    sleep_wake_epoch = 0;

    sleep_save_state();

    // Turn sensing back ON
    aq7_sensing_enabled = true;

    // Turn LCD backlight ON
    esp_err_t ret =
        wavesahre_rgb_lcd_bl_on();

    if (ret != ESP_OK)
    {
        ESP_LOGE(
            TAG,
            "LCD backlight ON failed: %s",
            esp_err_to_name(ret)
        );
    }

    // Restore normal UI
    if (sleep_timer_container)
    {
        lv_obj_clear_flag(
            sleep_timer_container,
            LV_OBJ_FLAG_HIDDEN
        );
    }

    if (sleep_status_label)
    {
        lv_obj_add_flag(
            sleep_status_label,
            LV_OBJ_FLAG_HIDDEN
        );
    }

    if (set_timer_btn)
    {
        lv_obj_clear_flag(
            set_timer_btn,
            LV_OBJ_FLAG_HIDDEN
        );
    }

    if (sleep_schedule_container)
    {
        if (sleep_schedule_mode)
        {
            lv_obj_clear_flag(
                sleep_schedule_container,
                LV_OBJ_FLAG_HIDDEN
            );

            if (sleep_timer_container)
            {
                lv_obj_add_flag(
                    sleep_timer_container,
                    LV_OBJ_FLAG_HIDDEN
                );
            }
        }
        else
        {
            lv_obj_add_flag(
                sleep_schedule_container,
                LV_OBJ_FLAG_HIDDEN
            );

            if (sleep_timer_container)
            {
                lv_obj_clear_flag(
                    sleep_timer_container,
                    LV_OBJ_FLAG_HIDDEN
                );
            }
        }
    }

    if (sleep_off_btn)
    {
        lv_obj_add_flag(
            sleep_off_btn,
            LV_OBJ_FLAG_HIDDEN
        );
    }

    ESP_LOGI(TAG, "AQ7 WAKE - normal operation resumed");
}

static void sleep_timer_start_cb(lv_event_t *e)
{
    lv_obj_t *btn = lv_event_get_target(e);

    if (btn == NULL)
        return;

    /*
     * ========================================================
     * TIMER MODE ONLY
     * ========================================================
     */

    if (sleep_schedule_mode)
    {
        ESP_LOGI(
            TAG,
            "Set pressed in SCHEDULE mode"
        );

        if (sleep_wake_epoch == 0)
        {
            show_toast(
                "Select date and time first",
                COLOR_POOR,
                COLOR_TEXT
            );

            return;
        }

        time_t now;
        time(&now);

        if ((uint64_t)now >= sleep_wake_epoch)
        {
            show_toast(
                "Wake time must be in the future",
                COLOR_POOR,
                COLOR_TEXT
            );

            return;
        }

        sleep_schedule_set = true;

        ESP_LOGI(
            TAG,
            "SCHEDULE SET: wake_epoch=%llu",
            (unsigned long long)sleep_wake_epoch
        );

        /*
        * DO NOT turn OFF yet.
        *
        * Ask the user what to do:
        *  - Cancel
        *  - Turn Off Now
        *  - Add OFF Time
        */
        sleep_show_on_schedule_confirmation();

        return;
    }

    /*
     * ========================================================
     * Read D/H/M rollers
     * ========================================================
     */

    lv_obj_t *hours_roller =
        lv_obj_get_user_data(btn);

    lv_obj_t *minutes_roller =
        (lv_obj_t *)lv_event_get_user_data(e);

    if (hours_roller == NULL ||
        minutes_roller == NULL)
    {
        ESP_LOGE(
            TAG,
            "Timer rollers are NULL"
        );
        return;
    }

    /*
     * Days roller is stored separately.
     *
     * If your current days roller is available globally,
     * use sleep_days_roller directly.
     */

    int days =
        sleep_days_roller
        ? lv_roller_get_selected(
              sleep_days_roller
          )
        : 0;

    int hours =
        lv_roller_get_selected(
            hours_roller
        );

    int minutes =
        lv_roller_get_selected(
            minutes_roller
        ) * 5;

    /*
     * ========================================================
     * Convert D/H/M -> seconds
     * ========================================================
     */

    uint64_t duration_seconds =
        ((uint64_t)days * 86400ULL) +
        ((uint64_t)hours * 3600ULL) +
        ((uint64_t)minutes * 60ULL);

    if (duration_seconds == 0)
    {
        show_toast(
            "Timer must be greater than 0",
            COLOR_POOR,
            COLOR_TEXT
        );

        return;
    }

    /*
     * ========================================================
     * MONOTONIC DEADLINE
     * ========================================================
     */

    int64_t now_us =
        esp_timer_get_time();

    sleep_timer_deadline_us =
        now_us +
        ((int64_t)duration_seconds * 1000000LL);

    /*
     * Timer mode does NOT use wake_epoch.
     */

    sleep_wake_epoch = 0;

    sleep_schedule_set = true;

    ESP_LOGI(
        TAG,
        "TIMER SET: %d d %02d h %02d min",
        days,
        hours,
        minutes
    );

    ESP_LOGI(
        TAG,
        "TIMER DEBUG: now_us=%lld deadline_us=%lld duration=%llu sec",
        (long long)now_us,
        (long long)sleep_timer_deadline_us,
        (unsigned long long)duration_seconds
    );

    /*
     * Show status before entering OFF.
     */

    if (sleep_status_label)
    {
        char buf[64];

        snprintf(
            buf,
            sizeof(buf),
            "OFF • %d d %02d:%02d:00",
            days,
            hours,
            minutes
        );

        lv_label_set_text(
            sleep_status_label,
            buf
        );

        lv_obj_clear_flag(
            sleep_status_label,
            LV_OBJ_FLAG_HIDDEN
        );
    }

    /*
     * Enter OFF state.
     */

    // sleep_start_off_state();
    sleep_show_on_schedule_confirmation();
}

static void sleep_start_off_state(void)
{
    /*
     * ========================================================
     * TIMER MODE
     * ========================================================
     */
    if (!sleep_schedule_mode)
    {
        if (sleep_timer_deadline_us <= 0)
        {
            ESP_LOGE(
                TAG,
                "Cannot start TIMER: deadline not configured"
            );
            return;
        }
    }

    /*
     * ========================================================
     * SCHEDULE MODE
     * ========================================================
     */
    else
    {
        if (sleep_wake_epoch == 0)
        {
            ESP_LOGE(
                TAG,
                "Cannot start SCHEDULE: wake epoch not configured"
            );
            return;
        }
    }

    sleep_timer_active = true;

    sleep_save_state();

    sleep_enter_off_state();

    if (!sleep_countdown_timer)
    {
        sleep_countdown_timer =
            lv_timer_create(
                sleep_countdown_cb,
                1000,
                NULL
            );
    }

    ESP_LOGI(
        TAG,
        "Sleep OFF started: mode=%s",
        sleep_schedule_mode ? "SCHEDULE" : "TIMER"
    );
}

static void sleep_confirm_yes_cb(lv_event_t *e)
{
    LV_UNUSED(e);

    lv_obj_t *mbox = lv_event_get_current_target(e);

    if (mbox)
        // lv_obj_del_async(mbox);
        lv_obj_del(mbox);

    sleep_start_off_state();
}

static void sleep_confirmation_event_cb(lv_event_t *e)
{
    lv_obj_t *mbox =
        lv_event_get_current_target(e);

    if (lv_event_get_code(e) != LV_EVENT_VALUE_CHANGED)
        return;

    uint16_t id =
        lv_msgbox_get_active_btn(mbox);

    /*
     * Button order:
     *
     * 0 = Cancel
     * 1 = Turn Off Now
     * 2 = Add OFF Time
     */

    if (id == 0)
    {
        // lv_obj_del_async(mbox);
        lv_obj_del(mbox);
        return;
    }

    if (id == 1)
    {
        // lv_obj_del_async(mbox);
        lv_obj_del(mbox);

        /*
         * No OFF schedule.
         * Turn OFF immediately and wake at
         * the already configured ON time.
         */
        sleep_start_off_state();

        return;
    }

    if (id == 2)
    {
        // lv_obj_del_async(mbox);
        lv_obj_del(mbox);

        /*
         * Configure a future OFF time.
         */
        sleep_show_off_time_picker();

        return;
    }
}

static void sleep_show_on_schedule_confirmation(void)
{
    static const char *buttons[] = {
        "\nCancel\n",
        "\nTurn Off Now\n",
        "\nAdd OFF Time\n",
        ""
    };

    lv_obj_t *mbox =
        lv_msgbox_create(
            lv_scr_act(),
            "ON Schedule Set",
            "What would you like to do?",
            buttons,
            true
        );

    lv_obj_set_width(mbox, 500);

    lv_obj_center(mbox);

    lv_obj_t *btns = lv_msgbox_get_btns(mbox);

    if (btns)
    {
        lv_obj_set_width(btns, 480);

        lv_btnmatrix_set_btn_width(btns, 0, 2);
        lv_btnmatrix_set_btn_width(btns, 1, 4);
        lv_btnmatrix_set_btn_width(btns, 2, 4);

        lv_obj_set_style_text_font(
            btns,
            &lv_font_montserrat_16,
            LV_PART_ITEMS
        );
    }

    lv_obj_add_event_cb(
        mbox,
        sleep_confirmation_event_cb,
        LV_EVENT_VALUE_CHANGED,
        NULL
    );

    lv_obj_add_event_cb(
        mbox,
        sleep_confirmation_event_cb,
        LV_EVENT_CANCEL,
        NULL
    );

    lv_obj_add_event_cb(
        mbox,
        sleep_confirmation_event_cb,
        LV_EVENT_VALUE_CHANGED,
        NULL
    );

    lv_obj_add_event_cb(
        mbox,
        sleep_confirmation_event_cb,
        LV_EVENT_CANCEL,
        NULL
    );
}

static void sleep_timer_cancel_cb(lv_event_t *e)
{
    LV_UNUSED(e);

    // IMPORTANT:
    // This button does NOT immediately power down.
    // It opens the confirmation dialog.
    // sleep_show_confirmation();
    sleep_show_on_schedule_confirmation();
}

static void sleep_countdown_cb(lv_timer_t *timer)
{
    LV_UNUSED(timer);

    if (!sleep_timer_active)
        return;

    uint64_t remaining = 0;

    /*
     * ========================================================
     * TIMER MODE
     * D/H/M = RELATIVE duration
     * ========================================================
     */
    if (!sleep_schedule_mode)
    {
        int64_t now_us =
            esp_timer_get_time();

        if (now_us >= sleep_timer_deadline_us)
        {
            ESP_LOGW(
                TAG,
                "TIMER WAKE: deadline reached"
            );

            sleep_exit_off_state();
            return;
        }

        remaining =
            (uint64_t)(
                (sleep_timer_deadline_us - now_us)
                / 1000000LL
            );
    }

    /*
     * ========================================================
     * DATE + TIME MODE
     * Absolute calendar time
     * ========================================================
     */
    else
    {
        time_t now;
        time(&now);

        if ((uint64_t)now >= sleep_wake_epoch)
        {
            ESP_LOGW(
                TAG,
                "SCHEDULE WAKE: epoch reached"
            );

            sleep_exit_off_state();
            return;
        }

        remaining =
            sleep_wake_epoch -
            (uint64_t)now;
    }

    /*
     * Screen 6 may have been destroyed.
     */
    if (sleep_status_label == NULL)
        return;

    uint64_t days =
        remaining / 86400ULL;

    remaining %= 86400ULL;

    uint64_t hours =
        remaining / 3600ULL;

    remaining %= 3600ULL;

    uint64_t minutes =
        remaining / 60ULL;

    uint64_t seconds =
        remaining % 60ULL;

    char buf[96];

    if (days > 0)
    {
        snprintf(
            buf,
            sizeof(buf),
            "OFF • %llu d %02llu:%02llu:%02llu",
            (unsigned long long)days,
            (unsigned long long)hours,
            (unsigned long long)minutes,
            (unsigned long long)seconds
        );
    }
    else
    {
        snprintf(
            buf,
            sizeof(buf),
            "OFF • %02llu:%02llu:%02llu",
            (unsigned long long)hours,
            (unsigned long long)minutes,
            (unsigned long long)seconds
        );
    }

    lv_label_set_text(
        sleep_status_label,
        buf
    );
}

// ==========================================
// TOAST NOTIFICATION (Quick 2-second message)
// ==========================================
static void toast_auto_close_cb(lv_timer_t *timer)
{
    if (active_toast != NULL)
    {
        /*
         * Delete immediately.
         *
         * We are already inside the LVGL timer handler,
         * so there is no need to queue another asynchronous
         * deletion.
         */
        lv_obj_del(active_toast);

        active_toast = NULL;
    }

    if (timer != NULL)
    {
        lv_timer_del(timer);
    }
}

static void show_toast(const char *message, lv_color_t bg_color, lv_color_t text_color) {

    // Delete any existing toast first
    if (active_toast != NULL) {
        lv_obj_del(active_toast);
        active_toast = NULL;
    }

    // Create toast container at the top center
    active_toast = lv_obj_create(lv_scr_act());
    lv_obj_set_size(active_toast, 280, 50);
    lv_obj_align(active_toast, LV_ALIGN_TOP_MID, 0, 20);
    lv_obj_set_style_bg_color(active_toast, bg_color, 0);
    lv_obj_set_style_bg_opa(active_toast, LV_OPA_90, 0);
    lv_obj_set_style_radius(active_toast, 12, 0);
    lv_obj_set_style_border_width(active_toast, 0, 0);
    lv_obj_set_style_shadow_width(active_toast, 10, 0);
    lv_obj_set_style_shadow_opa(active_toast, LV_OPA_30, 0);
    
    lv_obj_t *label = lv_label_create(active_toast);
    lv_label_set_text(label, message);
    lv_obj_set_style_text_color(label, text_color, 0);
    lv_obj_set_style_text_font(label, &lv_font_montserrat_14, 0);
    lv_obj_center(label);
    
    lv_obj_move_foreground(active_toast);
    
    // Auto-close after 2 seconds
    lv_timer_t *timer = lv_timer_create(toast_auto_close_cb, 2000, NULL);
    lv_timer_set_repeat_count(timer, 1);
}

//Forward declaration for time and wifi
static char last_time[32] = "--:--";

char latest_report_filename[128] = "report.csv";

static bool merge_csv_files(int start_day, int end_day)
{
    bool include_stats = lv_obj_has_state(ui_CheckboxStats, LV_STATE_CHECKED);
    bool include_raw   = lv_obj_has_state(ui_CheckboxRaw, LV_STATE_CHECKED);
    // float values[10] = {0};
    ESP_LOGI(TAG, "Export options - Stats: %d, Raw: %d", include_stats, include_raw);

    // Ensure at least one export option is selected
    if (!include_stats && !include_raw) {
        ESP_LOGE(TAG, "Neither statistics nor raw data selected for export.");
        return false;
    }

    // if (xSemaphoreTake(spi_mutex, pdMS_TO_TICKS(5000)) != pdTRUE) {
    //     ESP_LOGE(TAG, "Failed to obtain SPI mutex");
    //     return false;
    // }
    if (xSemaphoreTake(sd_mutex, pdMS_TO_TICKS(5000)) != pdTRUE)
    {
        ESP_LOGE(TAG, "Failed to obtain SD mutex");
        // xSemaphoreGive(spi_mutex); 
        return false;
    }

    ch422g_set_sd_selected(true);

    FILE *dst = NULL;
    FILE *src = NULL;
    char src_name[128];

    report_stats_t stats = {0};
    stats.min_aqi = 100000.0f;
    stats.max_aqi = -100000.0f;

    // --- Generate Dynamic Output Path ---
    char dst_path[256];
    if (start_day == end_day) {
        snprintf(latest_report_filename, sizeof(latest_report_filename), "report_%08d.csv", start_day);
    } else {
        snprintf(latest_report_filename, sizeof(latest_report_filename), "report_%08d_to_%08d.csv", start_day, end_day);
    }
    snprintf(dst_path, sizeof(dst_path), MOUNT_POINT "/%s", latest_report_filename);

    ESP_LOGI(TAG, "Creating export report file: %s", dst_path);

    /* --- PASS 1: Calculate Statistics --- */
    struct tm date_tm = {0};
    date_tm.tm_year = (start_day / 10000) - 1900;
    date_tm.tm_mon  = ((start_day / 100) % 100) - 1;
    date_tm.tm_mday = start_day % 100;

    bool found_any_file = false;


    /* --- PASS 1: Calculate Statistics (Only if requested) --- */
    if (include_stats)
    {
        struct tm stats_tm = date_tm;
        while (1)
        {
            mktime(&stats_tm);
            int file_date = (stats_tm.tm_year + 1900) * 10000 + (stats_tm.tm_mon + 1) * 100 + stats_tm.tm_mday;
            if (file_date > end_day) break;

            snprintf(src_name, sizeof(src_name), MOUNT_POINT "/%08d.csv", file_date);
            src = fopen(src_name, "r");

            if (src != NULL)
            {
                found_any_file = true;
                char line[256];
                while (fgets(line, sizeof(line), src))
                {
                    size_t len = strlen(line);
                    while (len > 0 && (line[len - 1] == '\r' || line[len - 1] == '\n')) line[--len] = '\0';
                    if (len == 0 || strncmp(line, "Date", 4) == 0 || strncmp(line, "Time", 4) == 0) continue;

                    sensor_data_t sample = {0};
                    char date[16], time_str[16];
                    int parsed = 0;
                    
                    // Detect format
                    bool is_comma = (strchr(line, ',') != NULL);
                    
                    if (is_comma) {
                        // Old comma format
                        char *token = strtok(line, ",");
                        int col = 0;
                        while (token != NULL) {
                            if (col == 2)  sample.pm25     = atof(token);
                            else if (col == 3)  sample.temp     = atof(token);
                            else if (col == 4)  sample.humidity = atof(token);
                            else if (col == 5)  sample.pressure = atof(token);
                            else if (col == 6)  sample.gas      = atof(token);
                            else if (col == 7)  sample.tvoc     = atof(token);
                            else if (col == 8)  sample.eco2     = atof(token);
                            else if (col == 9)  sample.pm10     = atof(token);
                            else if (col == 10) sample.fan      = atoi(token);
                            else if (col == 11) sample.filter   = atoi(token);
                            else if (col == 12) sample.aqi      = atoi(token);
                            
                            token = strtok(NULL, ",");
                            col++;
                        }
                        
                        if (col >= 8) {
                            if (stats.samples == 0) {
                                stats.max_aqi = sample.aqi;
                                stats.min_aqi = sample.aqi;
                            } else {
                                if (sample.aqi > stats.max_aqi) stats.max_aqi = sample.aqi;
                                if (sample.aqi < stats.min_aqi) stats.min_aqi = sample.aqi;
                            }
                            stats.samples++;
                            stats.sum_aqi += sample.aqi;
                            stats.sum_pm25 += sample.pm25;
                            stats.sum_pm10 += sample.pm10;
                            stats.sum_temp += sample.temp;
                            stats.sum_humidity += sample.humidity;
                            stats.sum_tvoc += sample.tvoc;
                        }
                    } else {
                        // New tab format
                        parsed = sscanf(line, "%15[^,],%15[^,],%f,%f,%f,%f,%f,%f,%f,%f,%d,%d,%d",
                                        date, time_str, &sample.pm25, &sample.temp, &sample.humidity,
                                        &sample.pressure, &sample.gas, &sample.tvoc, &sample.eco2,
                                        &sample.pm10, &sample.fan_speed, &sample.filter_life, &sample.aqi);
                        // Debug first record
                        static int tab_debug = 0;
                        if (tab_debug++ < 3) {
                            ESP_LOGI(TAG, "Tab parse: pm25=%.1f fan=%d aqi=%d", (double)sample.pm25, sample.fan_speed, sample.aqi);
                        }
                    }

                    if (parsed >= 7) {
                        if (stats.samples == 0) {
                            stats.max_aqi = sample.aqi;
                            stats.min_aqi = sample.aqi;
                        } else {
                            if (sample.aqi > stats.max_aqi) stats.max_aqi = sample.aqi;
                            if (sample.aqi < stats.min_aqi) stats.min_aqi = sample.aqi;
                        }
                        stats.samples++;
                        stats.sum_aqi       += sample.aqi;
                        stats.sum_pm25      += sample.pm25;
                        stats.sum_pm10      += sample.pm10;
                        stats.sum_temp      += sample.temp;
                        stats.sum_humidity  += sample.humidity;
                        stats.sum_tvoc      += sample.tvoc;
                    }
                }
                fclose(src);
            }
            stats_tm.tm_mday++;
        }
    }

    else 
    {
        // If stats are skipped, quickly scan to ensure files exist for raw data copying
        struct tm check_tm = date_tm;
        while (1)
        {
            mktime(&check_tm);
            int file_date = (check_tm.tm_year + 1900) * 10000 + (check_tm.tm_mon + 1) * 100 + check_tm.tm_mday;
            if (file_date > end_day) break;

            snprintf(src_name, sizeof(src_name), MOUNT_POINT "/%08d.csv", file_date);
            src = fopen(src_name, "r");
            if (src != NULL) {
                found_any_file = true;
                fclose(src);
                break;
            }
            check_tm.tm_mday++;
        }
    }


    if (!found_any_file) {
        ESP_LOGE(TAG, "No daily CSV log files found for requested date range.");
        xSemaphoreGive(sd_mutex);
        return false;
    }

    /* Create Output Destination File */
    dst = fopen(dst_path, "w");
    if (dst == NULL) {
        ESP_LOGE(TAG, "Failed to create destination export file: errno=%d", errno);
        xSemaphoreGive(sd_mutex);
        return false;
    }

    if (include_stats) {
        /* Compute Averages only if stats are ticked*/
        float avg_aqi      = (stats.samples > 0) ? (stats.sum_aqi / stats.samples) : 0;
        float avg_pm25     = (stats.samples > 0) ? (stats.sum_pm25 / stats.samples) : 0;
        float avg_pm10     = (stats.samples > 0) ? (stats.sum_pm10 / stats.samples) : 0;
        float avg_temp     = (stats.samples > 0) ? (stats.sum_temp / stats.samples) : 0;
        float avg_humidity = (stats.samples > 0) ? (stats.sum_humidity / stats.samples) : 0;
        float avg_tvoc     = (stats.samples > 0) ? (stats.sum_tvoc / stats.samples) : 0;

        time_t now;
        struct tm timeinfo;
        time(&now);
        localtime_r(&now, &timeinfo);
        char gen_time[64];
        strftime(gen_time, sizeof(gen_time), "%Y-%m-%d %H:%M:%S", &timeinfo);

        /* Write Report Summary */
        fprintf(dst, "OPRUSS AQ7 AIR QUALITY REPORT\n\n");
        fprintf(dst, "Generated:\n%s\n\n", gen_time);
        fprintf(dst, "Period:\n%08d to %08d\n\n", start_day, end_day);
        fprintf(dst, "SUMMARY\nMetric,Value\n");
        fprintf(dst, "Samples,%lu\n", (unsigned long)stats.samples);
        fprintf(dst, "Average AQI,%.1f\nMaximum AQI,%.1f\nMinimum AQI,%.1f\n", avg_aqi, stats.max_aqi, stats.min_aqi);
        fprintf(dst, "Average PM2.5,%.1f\nAverage PM10,%.1f\nAverage Temp,%.1f\nAverage Hum,%.1f\nAverage TVOC,%.1f\n\n",
                avg_pm25, avg_pm10, avg_temp, avg_humidity, avg_tvoc);

    }

    /* --- PASS 2: Copy Raw Data Rows --- */
    if (include_stats) {
        fprintf(dst, "RAW DATA\nDate,Time,PM2.5,Temp,Humidity,Pressure,Gas,TVOC,eCO2,PM10,Fan Speed,Filter Life,AQI\n");

        struct tm raw_tm = date_tm;

        // date_tm.tm_year = (start_day / 10000) - 1900;
        // date_tm.tm_mon  = ((start_day / 100) % 100) - 1;
        // date_tm.tm_mday = start_day % 100;

        while (1)
        {
            mktime(&raw_tm);
            int file_date = (raw_tm.tm_year + 1900) * 10000 + (raw_tm.tm_mon + 1) * 100 + raw_tm.tm_mday;
            if (file_date > end_day) break;

            snprintf(src_name, sizeof(src_name), MOUNT_POINT "/%08d.csv", file_date);
            src = fopen(src_name, "r");

            if (src != NULL)
            {
                char line[256];
                while (fgets(line, sizeof(line), src))
                {
                    size_t len = strlen(line);
                    while (len > 0 && (line[len - 1] == '\r' || line[len - 1] == '\n')) line[--len] = '\0';
                    if (len == 0 || strncmp(line, "Date", 4) == 0 || strncmp(line, "Time", 4) == 0) continue;
                    fprintf(dst, "%s\n", line);
                }
                fclose(src);
            }
            raw_tm.tm_mday++;
        }
    }

    fclose(dst);

    // ADDED THIS TO Verify file was actually written
    struct stat dst_st;
    if (stat(dst_path, &dst_st) == 0) {
        ESP_LOGI(TAG, "Report written to %s, size=%ld bytes", dst_path, (long)dst_st.st_size);
    } else {
        ESP_LOGE(TAG, "Report file not found after writing: %s", dst_path);
    }

    ESP_LOGI(TAG, "Report written to %s", dst_path);
    ch422g_set_sd_selected(false);
    xSemaphoreGive(sd_mutex);
    // xSemaphoreGive(spi_mutex);
    return true;
}

static void export_processing_task(void *pvParameters) {
    export_task_params_t *params = (export_task_params_t *)pvParameters;
    
    // Perform the heavy SD card blocking operation here
    bool success = merge_csv_files(params->start_day, params->end_day);
    if (success && params->is_email) {

        esp_err_t err =
            send_report_via_email(params->email,
                                latest_report_filename);

        if (err != ESP_OK) {
            ESP_LOGE(TAG, "Email send failed");
        }
    }
    
    // We must pass the result back to the LVGL main thread safely
    // LVGL is NOT thread-safe, so we use lv_async_call
    void * result_ptr = (void *)(size_t)(success ? (params->is_email ? 1 : 2) : 0);
    
    lv_async_call(export_complete_cb, result_ptr);
    
    free(params);
    vTaskDelete(NULL);
}

// This runs on the main LVGL thread AFTER the background task finishes
static void export_complete_cb(void * result_ptr) {
    int result = (int)(size_t)result_ptr;
    
    // Remove loading overlay here (assuming you stored the loading overlay pointer globally)
    // if (loading_overlay) { lv_obj_del(loading_overlay); loading_overlay = NULL; }

    if (result == 1) { // Success - Email
        ESP_LOGI(TAG, "CSV Merge Successful, prompting for email.");
        if (export_popup != NULL) {
            lv_obj_del(export_popup);
            export_popup = NULL;
        }
        // Show success toast
        show_toast(LV_SYMBOL_OK "  Email sent successfully!", 
                   lv_color_hex(0x2ECC71),  // Green background
                   lv_color_white());
        ESP_LOGI(TAG, "Report generated and emailed successfully.");
    } 
    else if (result == 2) { // Success - Wi-Fi
        // Fetch IP and show QR code
        esp_netif_ip_info_t ip_info;
        esp_netif_t *netif = esp_netif_get_handle_from_ifkey("WIFI_STA_DEF");
        char download_url[128] = "http://192.168.1.1/download"; 
        if (netif && esp_netif_get_ip_info(netif, &ip_info) == ESP_OK) {
            snprintf(download_url, sizeof(download_url), "http://" IPSTR "/download", IP2STR(&ip_info.ip));
        }

        
        // Pass dummy dates or the original parameters if you store them globally
        show_export_qr(download_url, 0, 0); 
         // Show success toast
        show_toast(LV_SYMBOL_WIFI "  Report ready for download!", 
                   lv_color_hex(0x2ECC71),  // Green background
                   lv_color_white());
    } 
    else {
        ESP_LOGE(TAG, "CSV Merge Failed");
        // Show error toast
        show_toast(LV_SYMBOL_CLOSE "  Failed to generate report!", 
                   lv_color_hex(0xE74C3C),  // Red background
                   lv_color_white());
    }
}

static void calendar_event_cb(lv_event_t * e)
{
    
    ESP_LOGI(TAG, "Target=%p", lv_event_get_target(e));
    ESP_LOGI(TAG, "Current=%p", lv_event_get_current_target(e));
    ESP_LOGI(TAG, "Stored=%p", calendar_obj);

    lv_calendar_date_t date;

    bool ok = lv_calendar_get_pressed_date(calendar_obj, &date);

    ESP_LOGI(TAG, "Pressed=%d", ok);

    if(!ok) return;
    // ============================================================
    // SLEEP SCHEDULE DATE SELECTION
    // ============================================================

    if (sleep_calendar_selection)
    {
        sleep_wake_day = date.day;
        sleep_wake_month = date.month;
        sleep_wake_year = date.year;

        sleep_calendar_selection = false;

        if (calendar_modal != NULL)
        {
            lv_obj_del(calendar_modal);
            calendar_modal = NULL;
        }

        ESP_LOGI(
            TAG,
            "Sleep wake date selected: %02d/%02d/%04d",
            sleep_wake_day,
            sleep_wake_month,
            sleep_wake_year
        );

        return;
    }

    if(selecting_start_date)
    {
    custom_start_date = date;

    selecting_start_date = false;

    lv_label_set_text(calendar_title,
                      "Select End Date");
    
    selected_dates[0] = custom_start_date;

    lv_calendar_set_highlighted_dates(calendar_obj,
                                    selected_dates,
                                    1);

    return;
    }

    custom_end_date = date;

    selected_dates[1] = custom_end_date;

    lv_calendar_set_highlighted_dates(calendar_obj,
                                    selected_dates,
                                    2);

    ESP_LOGI(TAG,
            "Range %02d/%02d/%04d -> %02d/%02d/%04d",
            custom_start_date.day,
            custom_start_date.month,
            custom_start_date.year,
            custom_end_date.day,
            custom_end_date.month,
            custom_end_date.year);

    lv_obj_del_async(calendar_modal);

    calendar_modal = NULL;

    selecting_start_date = true;
 
    // Check if calendar was opened from Screen 3
    if (screen3_calendar_selection_start) {
        screen3_calendar_selection_start = false;  // Reset flag
        
        int start_day = (custom_start_date.year * 10000) + (custom_start_date.month * 100) + custom_start_date.day;
        int end_day = (custom_end_date.year * 10000) + (custom_end_date.month * 100) + custom_end_date.day;
        
        ESP_LOGI(TAG, "Screen 3 custom range: %d to %d", start_day, end_day);
        screen3_live_mode = false;
        screen3_selected_range = 3;


        /* Save selected range */
        settings_save_screen3_state(
            false,
            3
        );


        /* Save actual custom dates */
        settings_save_screen3_custom_range(
            start_day,
            end_day
        );
        screen3_parse_sd_range(start_day, end_day);
    }
}

