static esp_err_t send_report_via_email(const char *recipient, const char *filename) 
{
    char full_path[256];
    snprintf(full_path, sizeof(full_path), MOUNT_POINT "/%s", filename);
    // Use the Catalyst send-report route for raw CSV streaming
    char url[256] = "https://project-rainfall-60082868759.development.catalystserverless.in/server/project_rainfall_function/api/send-report";

    // Take SPI mutex first
    // if (xSemaphoreTake(spi_mutex, pdMS_TO_TICKS(5000)) != pdTRUE) {
    //     ESP_LOGE(TAG, "Failed to obtain SPI mutex for email");
    //     return ESP_FAIL;
    // }
    
    // Acquire SD mutex and select SD card via multiplexer before reading
    if (xSemaphoreTake(sd_mutex, pdMS_TO_TICKS(5000)) != pdTRUE) {
        ESP_LOGE(TAG, "Failed to obtain SD mutex for email attachment");
        // xSemaphoreGive(spi_mutex);
        return ESP_FAIL;
    }
    ch422g_set_sd_selected(true);

    // Check file size first (no file handle needed)
    struct stat st;
    long file_size = 0;
    int retries = 5;
    
    while (retries > 0) {
        if (stat(full_path, &st) == 0) {
            file_size = st.st_size;
            if (file_size > 0) {
                break;  // Got valid size
            }
        }
        ESP_LOGW(TAG, "File size check retry %d, size=%ld", 6 - retries, file_size);
        vTaskDelay(pdMS_TO_TICKS(200));  // Wait 200ms for file to be fully written
        retries--;
    }
    
    ESP_LOGI(TAG, "Report file size: %ld bytes (after %d retries)", file_size, 5 - retries);
    
    if (file_size <= 0) {
        ESP_LOGE(TAG, "Report file is empty or invalid: %s (tried 5 times)", full_path);
        
        // ADD: List directory to debug
        DIR *dir = opendir(MOUNT_POINT);
        if (dir) {
            ESP_LOGI(TAG, "SD card contents:");
            struct dirent *entry;
            while ((entry = readdir(dir)) != NULL) {
                char path[512];
                snprintf(path, sizeof(path), "%s/%s", MOUNT_POINT, entry->d_name);
                struct stat entry_st;
                if (stat(path, &entry_st) == 0) {
                    ESP_LOGI(TAG, "  %s - %ld bytes", entry->d_name, (long)entry_st.st_size);
                }
            }
            closedir(dir);
        }
        
        ch422g_set_sd_selected(false);
        xSemaphoreGive(sd_mutex);
        // xSemaphoreGive(spi_mutex);
        return ESP_FAIL;
    }

    // Open the CSV report file from the SD card
    FILE *f = fopen(full_path, "r");
    if (!f) {
        ESP_LOGE(TAG, "Could not open report file for email attachment: %s", full_path);
        ch422g_set_sd_selected(false);
        xSemaphoreGive(sd_mutex);
        // xSemaphoreGive(spi_mutex);
        return ESP_FAIL;
    }

    ESP_LOGI(TAG, "Preparing to send file %s (%ld bytes) to %s", filename, file_size, recipient);

    // Build the Google Apps Script URL
    // char url[512];
    // snprintf(url, sizeof(url), "https://script.google.com/macros/s/AKfycbyWsE1NQBw6Tg1kBvmZU74L3HfXsRbuxs8D3z4diTqX4HmqbbaAhzI9djDVZSIIxYxO/exec?recipient=%s&filename=%s", recipient, filename);
    // ESP_LOGI(TAG, "Sending to URL: %s", url);

    esp_http_client_config_t config = {
        .url = url,
        .method = HTTP_METHOD_POST,
        .timeout_ms = 60000,
        .buffer_size = 4096,
        .buffer_size_tx = 4096,
        .keep_alive_enable = true,  //keep connection alive
        .crt_bundle_attach = esp_crt_bundle_attach,
    };
    
    esp_http_client_handle_t client = esp_http_client_init(&config);
    if (client == NULL) {
        ESP_LOGE(TAG, "Failed to initialize ESP HTTP client");
        fclose(f);
        ch422g_set_sd_selected(false);
        xSemaphoreGive(sd_mutex);
        // xSemaphoreGive(spi_mutex);
        return ESP_FAIL;
    }

    // Set headers
    esp_http_client_set_header(client, "Content-Type", "text/csv");
    esp_http_client_set_header(client, "X-Recipient-Email", recipient);
    esp_http_client_set_header(client, "X-File-Name", filename);

    // Open connection and stream file data chunk-by-chunk
    esp_err_t err = esp_http_client_open(client, file_size);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Failed to open HTTP connection: %s", esp_err_to_name(err));
        fclose(f);
        ch422g_set_sd_selected(false);
        xSemaphoreGive(sd_mutex);
        // xSemaphoreGive(spi_mutex);
        esp_http_client_cleanup(client);
        return err;
    }

    char chunk[1024];
    size_t read_bytes;
    long total_sent = 0;

    while ((read_bytes = fread(chunk, 1, sizeof(chunk), f)) > 0) {
        int written = esp_http_client_write(client, chunk, read_bytes);
        if (written < 0) {
            ESP_LOGE(TAG, "Failed to write data chunk to HTTP stream");
            err = ESP_FAIL;
            break;
        }
        total_sent += written;
        
        // Log progress for large files
        if (total_sent % 100000 == 0) {
            ESP_LOGI(TAG, "Sent %ld / %ld bytes", total_sent, file_size);
        }
    }
    
    fclose(f);
    ch422g_set_sd_selected(false);
    xSemaphoreGive(sd_mutex);
    // xSemaphoreGive(spi_mutex);

    if (err == ESP_OK) {
        // Fetch response status from server
        int content_length = esp_http_client_fetch_headers(client);
        int status_code = esp_http_client_get_status_code(client);

        ESP_LOGI(TAG, "HTTP Status: %d, Content-Length: %d", status_code, content_length);
        
        if (status_code == 200 || status_code == 302) {
            ESP_LOGI(TAG, "Email dispatched successfully (Status: %d)", status_code);
        } else {
            ESP_LOGE(TAG, "Server returned failure status code: %d", status_code);
            err = ESP_FAIL;
        }
    }

    esp_http_client_cleanup(client);
    return err;
}

static void email_kb_event_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    // lv_obj_t *kb = lv_event_get_target(e);

    if (code == LV_EVENT_READY || code == LV_EVENT_CANCEL) {
        if (code == LV_EVENT_READY) {
            if (email_ta != NULL) {
                const char *recipient_email = lv_textarea_get_text(email_ta);

                if (recipient_email && strlen(recipient_email) > 0) {

                    export_task_params_t *params =
                        malloc(sizeof(export_task_params_t));

                    if (!params) {
                        ESP_LOGE(TAG, "Failed to allocate export task");
                        return;
                    }

                    params->start_day = g_export_start_day;
                    params->end_day   = g_export_end_day;
                    params->is_email  = true;

                    strncpy(params->email,
                            recipient_email,
                            sizeof(params->email) - 1);

                    params->email[sizeof(params->email)-1] = '\0';

                    // Clean up keyboard and modal
                    if (email_modal != NULL) {
                        lv_obj_del(email_modal);
                        email_modal = NULL;
                        email_ta = NULL;
                        email_kb = NULL;
                    }

                    // Show "sending" toast
                    show_toast(LV_SYMBOL_ENVELOPE "  Sending email...", 
                            lv_color_hex(0xF27330),  // Orange background
                            lv_color_white());

                    // Small delay then start export task
                    vTaskDelay(pdMS_TO_TICKS(500));

                    xTaskCreate(export_processing_task,
                                "export_task",
                                8192,
                                params,
                                5,
                                NULL);
                }
            }
        } 
        else if (code == LV_EVENT_CANCEL) {
            ESP_LOGI(TAG, "Email input modal cancelled by user.");
        }
        
        // Clean up the entire modal overlay, text area, and keyboard objects
        if (email_modal != NULL) {
            lv_obj_del(email_modal);
            email_modal = NULL;
            email_ta = NULL;
            email_kb = NULL;
        }
    }
}

static void export_email_cb(lv_event_t * e) {
    lv_obj_t *dd = lv_event_get_user_data(e);
    char period[32];
    lv_dropdown_get_selected_str(dd, period, sizeof(period));

    int start_day, end_day;
    
    if(strcmp(period, "Custom Range") == 0) {
        start_day = (custom_start_date.year * 10000) + (custom_start_date.month * 100) + custom_start_date.day;
        end_day = (custom_end_date.year * 10000) + (custom_end_date.month * 100) + custom_end_date.day;
    } else {
        time_t now;
        time(&now);
        struct tm start_tm = *localtime(&now);
        struct tm end_tm = *localtime(&now);

        if (strcmp(period, "Last 7 Days") == 0) {
            start_tm.tm_mday -= 6;
        } else if(strcmp(period, "Last Month") == 0) {
            start_tm.tm_mday -= 29; // Or 30 based on your preference
        } // "Today" keeps tm_mday as-is

        mktime(&start_tm); // Normalize dates
        mktime(&end_tm);

        start_day = (start_tm.tm_year + 1900) * 10000 + (start_tm.tm_mon + 1) * 100 + start_tm.tm_mday;
        end_day = (end_tm.tm_year + 1900) * 10000 + (end_tm.tm_mon + 1) * 100 + end_tm.tm_mday;
    }

    ESP_LOGI(TAG, "Merge Range Selected: %d -> %d", start_day, end_day);

    // Call your existing merge function (which checks ui_CheckboxStats & ui_CheckboxRaw)
    // if(merge_csv_files(start_day, end_day)) {
    //     ESP_LOGI(TAG, "CSV Merge Successful, prompting for email.");
        
    //     // Close the export popup to clean up the screen
    //     if(export_popup != NULL) {
    //         lv_obj_del(export_popup);
    //         export_popup = NULL;
    //     }
        
    //     // Open the virtual keyboard
    //     open_email_input_modal();
    // } else {
    //     ESP_LOGE(TAG, "CSV Merge Failed");
    //     // Optionally show an error message box here
    // }
    // --- REPLACE MERGE CALL WITH THIS ---
    // // Allocate parameters dynamically so they survive after the callback exits
    // export_task_params_t *params = malloc(sizeof(export_task_params_t));
    // params->start_day = start_day;
    // params->end_day = end_day;
    
    // // Set to true if inside export_email_cb, false if inside export_wifi_cb
    // params->is_email = true; 

    // // Spawn FreeRTOS background task so LVGL doesn't freeze
    // xTaskCreate(export_processing_task, "export_task", 8192, params, 5, NULL);
    if (export_popup != NULL) {
        lv_obj_del(export_popup);
        export_popup = NULL;
    }

    /* Save the dates globally */
    g_export_start_day = start_day;
    g_export_end_day   = end_day;

    /* Open keyboard immediately */
    open_email_input_modal();
}

static void open_email_input_modal(void) {
    if (email_modal != NULL) return;

    // 1. Full-screen dimmed backdrop overlay
    email_modal = lv_obj_create(lv_scr_act());
    lv_obj_set_size(email_modal, LV_PCT(100), LV_PCT(100));
    lv_obj_set_style_bg_color(email_modal, lv_color_black(), 0);
    lv_obj_set_style_bg_opa(email_modal, LV_OPA_50, 0); // 50% opacity backdrop
    lv_obj_set_style_border_width(email_modal, 0, 0);
    lv_obj_set_style_pad_all(email_modal, 0, 0);
    lv_obj_clear_flag(email_modal, LV_OBJ_FLAG_SCROLLABLE);

    // 2. Floating Dialog Card Container
    lv_obj_t * email_card = lv_obj_create(email_modal);
    lv_obj_set_size(email_card, 440, 270);              // Dimensions for floating card
    lv_obj_center(email_card);                           // Center floating card on screen
    lv_obj_set_style_bg_color(email_card, COLOR_CARD, 0);
    lv_obj_set_style_border_color(email_card, COLOR_ACCENT, 0);
    lv_obj_set_style_border_width(email_card, 2, 0);
    lv_obj_set_style_radius(email_card, 12, 0);          // Rounded corners
    lv_obj_set_style_shadow_width(email_card, 24, 0);    // Drop shadow
    lv_obj_set_style_shadow_opa(email_card, LV_OPA_40, 0);
    lv_obj_clear_flag(email_card, LV_OBJ_FLAG_SCROLLABLE);

    // 3. Instruction Label inside the card
    lv_obj_t * instruction = lv_label_create(email_card);
    lv_label_set_text(instruction, "Enter Recipient Email Address:");
    lv_obj_set_style_text_color(instruction, COLOR_TEXT, 0);
    lv_obj_align(instruction, LV_ALIGN_TOP_LEFT, 5, 0);

    // 4. Text Area inside the card
    email_ta = lv_textarea_create(email_card);
    lv_textarea_set_one_line(email_ta, true);
    lv_textarea_set_placeholder_text(email_ta, "opruss@example.com");
    lv_obj_set_width(email_ta, 410);
    lv_obj_align(email_ta, LV_ALIGN_TOP_MID, 0, 28);

    // 5. Floating Virtual Keyboard constrained to the card
    email_kb = lv_keyboard_create(email_card);
    lv_keyboard_set_mode(email_kb, LV_KEYBOARD_MODE_TEXT_LOWER); 
    lv_keyboard_set_textarea(email_kb, email_ta);
    lv_obj_set_size(email_kb, 410, 160);                 // Compact size fitting the card
    lv_obj_align(email_kb, LV_ALIGN_BOTTOM_MID, 0, 0);

    // Bind Keyboard Events
    lv_obj_add_event_cb(email_kb, email_kb_event_cb, LV_EVENT_READY, NULL);
    lv_obj_add_event_cb(email_kb, email_kb_event_cb, LV_EVENT_CANCEL, NULL);
}

