static void close_wifi_qr_cb(lv_event_t *e)
{
    LV_UNUSED(e);
    if (wifi_qr_popup != NULL) {
        lv_obj_del(wifi_qr_popup);
        wifi_qr_popup = NULL;
        wifi_qr_code = NULL;
        wifi_qr_status = NULL;
        wifi_qr_url_label = NULL;
    }
}

static void update_wifi_qr_cb(void *data)
{
    wifi_qr_update_data_t *qr_data = (wifi_qr_update_data_t *)data;
    
    if (wifi_qr_popup == NULL) {
        free(qr_data);
        return;
    }
    
    lv_obj_t *qr_container = lv_obj_get_user_data(wifi_qr_popup);
    
    if (qr_data->success) {
        // Update status text
        if (wifi_qr_status) {
            lv_label_set_text(wifi_qr_status, "Scan to download report");
            lv_obj_set_style_text_color(wifi_qr_status, lv_color_hex(0x2ECC71), 0);
        }
        
        // Replace spinner with QR code
        if (qr_container) {
            lv_obj_clean(qr_container);
            
#if LV_USE_QRCODE
            wifi_qr_code = lv_qrcode_create(qr_container, 160, lv_color_black(), lv_color_white());
            lv_qrcode_update(wifi_qr_code, qr_data->url, strlen(qr_data->url));
            lv_obj_center(wifi_qr_code);
            lv_obj_clear_flag(wifi_qr_code, LV_OBJ_FLAG_SCROLLABLE);
#endif
        }
        
        if (wifi_qr_url_label) {
            lv_label_set_text(wifi_qr_url_label, qr_data->url);
            lv_obj_set_width(wifi_qr_url_label, LV_SIZE_CONTENT);  // Auto-width based on text
            lv_obj_align(wifi_qr_url_label, LV_ALIGN_BOTTOM_MID, 0, -50);  // Re-center
        }
        
    } else {
        if (wifi_qr_status) {
            lv_label_set_text(wifi_qr_status, "Failed to generate report");
            lv_obj_set_style_text_color(wifi_qr_status, lv_color_hex(0xE74C3C), 0);
        }
        
        if (qr_container) {
            lv_obj_clean(qr_container);
            lv_obj_t *error_lbl = lv_label_create(qr_container);
            lv_label_set_text(error_lbl, LV_SYMBOL_CLOSE "\nError");
            lv_obj_set_style_text_color(error_lbl, lv_color_hex(0xE74C3C), 0);
            lv_obj_center(error_lbl);
        }
        
        if (wifi_qr_url_label) {
            lv_label_set_text(wifi_qr_url_label, "Please try again");
        }
    }
    
    free(qr_data);
}

static void show_wifi_export_qr_loading(int start_day, int end_day)
{
    // Create popup
    wifi_qr_popup = lv_obj_create(lv_scr_act());
    lv_obj_set_size(wifi_qr_popup, 400, 420);
    lv_obj_center(wifi_qr_popup);
    lv_obj_set_style_bg_color(wifi_qr_popup, lv_color_hex(0x1A1A2E), 0);
    lv_obj_set_style_border_color(wifi_qr_popup, lv_color_hex(0xF27330), 0);
    lv_obj_set_style_border_width(wifi_qr_popup, 2, 0);
    lv_obj_set_style_radius(wifi_qr_popup, 16, 0);
    lv_obj_set_style_pad_all(wifi_qr_popup, 15, 0);
    lv_obj_clear_flag(wifi_qr_popup, LV_OBJ_FLAG_SCROLLABLE);

    // ===== 1. TITLE =====
    lv_obj_t *title = lv_label_create(wifi_qr_popup);
    lv_label_set_text(title, "Wi-Fi Export Ready");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_18, 0);
    lv_obj_set_style_text_color(title, lv_color_white(), 0);
    lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 5);

    // ===== 2. PERIOD =====
    lv_obj_t *range_lbl = lv_label_create(wifi_qr_popup);
    char range[64];
    snprintf(range, sizeof(range), "Period: %08d to %08d", start_day, end_day);
    lv_label_set_text(range_lbl, range);
    lv_obj_set_style_text_color(range_lbl, lv_color_hex(0xAAAAAA), 0);
    lv_obj_set_style_text_font(range_lbl, &lv_font_montserrat_12, 0);
    lv_obj_align(range_lbl, LV_ALIGN_TOP_MID, 0, 30);

    // ===== 3. "SCAN TO DOWNLOAD" STATUS =====
    wifi_qr_status = lv_label_create(wifi_qr_popup);
    lv_label_set_text(wifi_qr_status, "Generating report...");
    lv_obj_set_style_text_color(wifi_qr_status, lv_color_hex(0xF27330), 0);
    lv_obj_set_style_text_font(wifi_qr_status, &lv_font_montserrat_14, 0);
    lv_obj_align(wifi_qr_status, LV_ALIGN_TOP_MID, 0, 55);

    // ===== 4. QR CODE CONTAINER (Center) =====
    lv_obj_t *qr_container = lv_obj_create(wifi_qr_popup);
    lv_obj_set_size(qr_container, 170, 170);
    lv_obj_align(qr_container, LV_ALIGN_CENTER, 0, 15);
    lv_obj_set_style_bg_color(qr_container, lv_color_white(), 0);
    lv_obj_set_style_border_width(qr_container, 0, 0);
    lv_obj_set_style_radius(qr_container, 8, 0);
    lv_obj_clear_flag(qr_container, LV_OBJ_FLAG_SCROLLABLE);
    
    // Spinner inside QR container
    lv_obj_t *spinner = lv_spinner_create(qr_container, 1000, 60);
    lv_obj_set_size(spinner, 60, 60);
    lv_obj_center(spinner);
    lv_obj_set_style_arc_color(spinner, lv_color_hex(0xF27330), LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(spinner, lv_color_hex(0xDDDDDD), LV_PART_MAIN);
    
    // Store QR container reference
    lv_obj_set_user_data(wifi_qr_popup, qr_container);

    // ===== 5. URL LABEL (Centered below QR code) =====
    wifi_qr_url_label = lv_label_create(wifi_qr_popup);
    lv_label_set_text(wifi_qr_url_label, "");
    lv_obj_set_style_text_color(wifi_qr_url_label, lv_color_hex(0x888888), 0);
    lv_obj_set_style_text_font(wifi_qr_url_label, &lv_font_montserrat_10, 0);
    lv_obj_set_style_text_align(wifi_qr_url_label, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_align(wifi_qr_url_label, LV_ALIGN_BOTTOM_MID, 0, -50);
    lv_obj_set_width(wifi_qr_url_label, 370);  // Fixed width, no scrolling

    // ===== 6. CLOSE BUTTON =====
    lv_obj_t *close_btn = lv_btn_create(wifi_qr_popup);
    lv_obj_set_size(close_btn, 120, 38);
    lv_obj_align(close_btn, LV_ALIGN_BOTTOM_MID, 0, -5);
    lv_obj_set_style_bg_color(close_btn, lv_color_hex(0xF27330), 0);
    lv_obj_set_style_radius(close_btn, 8, 0);
    
    lv_obj_t *btn_lbl = lv_label_create(close_btn);
    lv_label_set_text(btn_lbl, "Close");
    lv_obj_set_style_text_color(btn_lbl, lv_color_white(), 0);
    lv_obj_center(btn_lbl);
    
    lv_obj_add_event_cb(close_btn, close_wifi_qr_cb, LV_EVENT_CLICKED, NULL);
}

static void export_wifi_cb(lv_event_t * e)
{
    lv_obj_t *dd = lv_event_get_user_data(e);
    char period[32];
    lv_dropdown_get_selected_str(dd, period, sizeof(period));

    ESP_LOGI(TAG, "Wi-Fi selected : %s", period);

    int start_day = 0;
    int end_day = 0;

    if(strcmp(period, "Custom Range") == 0)
    {
        start_day = (custom_start_date.year * 10000) + (custom_start_date.month * 100) + custom_start_date.day;
        end_day = (custom_end_date.year * 10000) + (custom_end_date.month * 100) + custom_end_date.day;
    }
    else
    {
        time_t now;
        time(&now);
        struct tm start_tm = *localtime(&now);
        struct tm end_tm = *localtime(&now);

        if(strcmp(period, "Last 7 Days") == 0) {
            start_tm.tm_mday -= 6;
        } else if(strcmp(period, "Last Month") == 0) {
            start_tm.tm_mday -= 29;
        }

        mktime(&start_tm);
        mktime(&end_tm);

        start_day = (start_tm.tm_year + 1900) * 10000 + (start_tm.tm_mon + 1) * 100 + start_tm.tm_mday;
        end_day = (end_tm.tm_year + 1900) * 10000 + (end_tm.tm_mon + 1) * 100 + end_tm.tm_mday;
    }

    ESP_LOGI(TAG, "Merge Range : %d -> %d", start_day, end_day);

    // Close export popup immediately
    if (export_popup != NULL) {
        lv_obj_del(export_popup);
        export_popup = NULL;
    }

    // Show QR code popup IMMEDIATELY with loading state
    show_wifi_export_qr_loading(start_day, end_day);

    // Start background task for merge
    export_task_params_t *params = malloc(sizeof(export_task_params_t));
    if (params == NULL) {
        ESP_LOGE(TAG, "Failed to allocate export task params");
        return;
    }
    params->start_day = start_day;
    params->end_day = end_day;
    params->is_email = false;

    xTaskCreate(export_processing_task_wifi, "export_wifi_task", 8192, params, 5, NULL);
}

static void export_processing_task_wifi(void *pvParameters)
{
    export_task_params_t *params = (export_task_params_t *)pvParameters;
    
    // Merge files
    bool success = merge_csv_files(params->start_day, params->end_day);
    
    if (success) {
        // Get the device IP
        esp_netif_ip_info_t ip_info;
        esp_netif_t *netif = esp_netif_get_handle_from_ifkey("WIFI_STA_DEF");
        char download_url[256] = "http://192.168.4.1/download";
        
        if (netif && esp_netif_get_ip_info(netif, &ip_info) == ESP_OK) {
            snprintf(download_url, sizeof(download_url), 
                     "http://" IPSTR "/download?file=%s", 
                     IP2STR(&ip_info.ip), latest_report_filename);
        }
        
        // Update QR code on main LVGL thread
        wifi_qr_update_data_t *qr_data = malloc(sizeof(wifi_qr_update_data_t));
        if (qr_data) {
            strncpy(qr_data->url, download_url, sizeof(qr_data->url) - 1);
            qr_data->success = true;
            lv_async_call(update_wifi_qr_cb, qr_data);
        }
    } else {
        wifi_qr_update_data_t *qr_data = malloc(sizeof(wifi_qr_update_data_t));
        if (qr_data) {
            qr_data->success = false;
            lv_async_call(update_wifi_qr_cb, qr_data);
        }
    }
    
    free(params);
    vTaskDelete(NULL);
}

// Call this function when the export popup opens and merge succeeds:
void show_export_qr_popup(lv_obj_t *parent, const char *start_date, const char *end_date) {
    // 1. Get the current local IP address assigned to the ESP32
    esp_netif_ip_info_t ip_info;
    esp_netif_t *netif = esp_netif_get_handle_from_ifkey("WIFI_STA_DEF");
    if (netif == NULL) {
        // Fallback or handle error
        return;
    }
    esp_netif_get_ip_info(netif, &ip_info);

    // 2. Format the download URL string dynamically
    char url_buf[128];
    snprintf(url_buf, sizeof(url_buf), "http://" IPSTR "/download?start=%s&end=%s", 
             IP2STR(&ip_info.ip), start_date, end_date);

    // 3. Create a container or modal box for the popup
    lv_obj_t *box = lv_obj_create(parent);
    lv_obj_set_size(box, 240, 260);
    lv_obj_center(box);

    // 4. Create the QR code object (requires LVGL's QR code component enabled)
    // Size of QR code matrix (e.g., 150x150 pixels)
    lv_obj_t *qrcode = lv_qrcode_create(box, 150, lv_color_black(), lv_color_white());
    lv_obj_align(qrcode, LV_ALIGN_TOP_MID, 0, 10);

    // 5. Set the data/URL payload into the QR code
    lv_qrcode_update(qrcode, url_buf, strlen(url_buf));

    // 6. Optional: Add a label below showing the raw text link
    lv_obj_t *lbl_url = lv_label_create(box);
    lv_label_set_text(lbl_url, url_buf);
    lv_obj_set_style_text_font(lbl_url, &lv_font_montserrat_10, 0);
    lv_obj_align(lbl_url, LV_ALIGN_BOTTOM_MID, 0, -5);
}

static void show_export_qr(const char *url, int start_day, int end_day)
{
    if (export_popup != NULL) {
        lv_obj_del(export_popup);
        export_popup = NULL;
    }

    // Container Window
    export_popup = lv_obj_create(lv_scr_act());
    lv_obj_center(export_popup);
    lv_obj_set_size(export_popup, 380, 320);
    lv_obj_set_style_bg_color(export_popup, lv_color_hex(0x222222), 0);
    lv_obj_set_style_border_color(export_popup, lv_color_hex(0x00A8FF), 0);
    lv_obj_set_style_border_width(export_popup, 2, 0);
    lv_obj_set_style_radius(export_popup, 12, 0);

    /* Modal Header */
    lv_obj_t *download_title = lv_label_create(export_popup);
    lv_label_set_text(download_title, "Export Ready Over Wi-Fi");
    lv_obj_align(download_title, LV_ALIGN_TOP_MID, 0, 10);

    /* Date Range Label */
    lv_obj_t *export_range_label = lv_label_create(export_popup);
    char range[64];
    snprintf(range, sizeof(range), "Period: %08d to %08d", start_day, end_day);
    lv_label_set_text(export_range_label, range);
    lv_obj_align(export_range_label, LV_ALIGN_TOP_MID, 0, 35);

#if LV_USE_QRCODE
    /* LVGL v8 QR Code Creation */
    lv_obj_t * export_qr = lv_qrcode_create(export_popup, 140, lv_color_black(), lv_color_white());
    lv_qrcode_update(export_qr, url, strlen(url));
    lv_obj_align(export_qr, LV_ALIGN_CENTER, 0, -5);
#else
    /* Fallback Label Displaying the IP/URL string directly */
    lv_obj_t *url_lbl = lv_label_create(export_popup);
    lv_label_set_text(url_lbl, url);
    lv_obj_align(url_lbl, LV_ALIGN_CENTER, 0, -5);
#endif

    /* Close Button */
    lv_obj_t *close_btn = lv_btn_create(export_popup);
    lv_obj_set_size(close_btn, 100, 36);
    lv_obj_align(close_btn, LV_ALIGN_BOTTOM_MID, 0, -10);
    
    // Wire up button event to delete export_popup
    lv_obj_add_event_cb(close_btn, close_popup_cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *lbl = lv_label_create(close_btn);
    lv_label_set_text(lbl, "Done");
    lv_obj_center(lbl);
}

static void export_dropdown_cb(lv_event_t * e)
{
    lv_obj_t * dropdown = lv_event_get_target(e);
    char buf[32];
    lv_dropdown_get_selected_str(dropdown, buf, sizeof(buf));

    if(strcmp(buf, "Custom Range") == 0)
    {
        create_calendar_modal();
    }
    else
    {
        // Update export dates when dropdown changes
        time_t now;
        time(&now);
        struct tm start_tm = *localtime(&now);
        struct tm end_tm = *localtime(&now);

        if(strcmp(buf, "Last 7 Days") == 0) {
            start_tm.tm_mday -= 6;
        } else if(strcmp(buf, "Last Month") == 0) {
            start_tm.tm_mday -= 29;
        }
        // "Today" keeps dates as-is

        mktime(&start_tm);
        mktime(&end_tm);

        g_export_start_day = (start_tm.tm_year + 1900) * 10000 + (start_tm.tm_mon + 1) * 100 + start_tm.tm_mday;
        g_export_end_day = (end_tm.tm_year + 1900) * 10000 + (end_tm.tm_mon + 1) * 100 + end_tm.tm_mday;
        
        ESP_LOGI(TAG, "Export range updated: %d -> %d", g_export_start_day, g_export_end_day);
    }
}


