// ==========================================
// SCREEN 3 RANGE DROPDOWN CALLBACK
// ==========================================
static void screen3_range_dropdown_cb(lv_event_t * e) {
    lv_obj_t * dropdown = lv_event_get_target(e);
    char buf[32];
    lv_dropdown_get_selected_str(dropdown, buf, sizeof(buf));

    ESP_LOGI(TAG, "Screen 3 range selected: %s", buf);

    if (strcmp(buf, "Today") == 0)
    {
        screen3_selected_range = 0;

        screen3_set_live_mode();

        settings_save_screen3_state(
            true,
            screen3_selected_range
        );
    }
    
    else if (strcmp(buf, "Last Week") == 0)
    {
        screen3_selected_range = 1;

        screen3_load_historical_range(7);

        settings_save_screen3_state(
            false,
            screen3_selected_range
        );
    }

    else if (strcmp(buf, "Last Month") == 0)
    {
        screen3_selected_range = 2;

        screen3_load_historical_range(30);

        settings_save_screen3_state(
            false,
            screen3_selected_range
        );
    }
    else if (strcmp(buf, "Custom Range") == 0)
    {
        screen3_selected_range = 3;

        settings_save_screen3_state(
            false,
            screen3_selected_range
        );

        screen3_calendar_selection_start =
            true;

        create_calendar_modal();
    }
}

// Switch to live data mode
static void screen3_set_live_mode(void) {
    screen3_live_mode = true;
    ESP_LOGI(TAG, "Screen 3: Live mode");
    // Reset all stats to real-time calculations
    screen3_reset_daily_stats();
    ui_refresh_screen3_display();
}

// Load historical data from SD card
static void screen3_load_historical_range(int days_back) {
    screen3_live_mode = false;
    
    time_t now;
    struct tm timeinfo;
    time(&now);
    localtime_r(&now, &timeinfo);
    
    // Calculate start date
    struct tm start_tm = timeinfo;
    // start_tm.tm_mday -= days_back;
    start_tm.tm_mday -= (days_back - 1);
    mktime(&start_tm);
    
    int start_day = (start_tm.tm_year + 1900) * 10000 + (start_tm.tm_mon + 1) * 100 + start_tm.tm_mday;
    int end_day = (timeinfo.tm_year + 1900) * 10000 + (timeinfo.tm_mon + 1) * 100 + timeinfo.tm_mday;
    
    ESP_LOGI(TAG, "Loading historical: %d to %d", start_day, end_day);
    screen3_parse_sd_range(start_day, end_day);
}

// Parse SD card CSV files for a date range and update display
static void screen3_reset_daily_stats(void) {
    s3_daily_aqi_sum = 0;
    s3_daily_samples = 0;
    s3_daily_aqi_max = 0;
    s3_daily_aqi_min = 999;
    s3_daily_pm25_sum = 0;
    s3_daily_pm10_sum = 0;
    s3_daily_temp_sum = 0;
    s3_daily_hum_sum = 0;
    s3_daily_tvoc_sum = 0;
    s3_compliant_hours = 0;
    s3_total_hours = 0;
    s3_peak_hour = 0;
    s3_peak_aqi = 0;
}

