static void wifi_network_selected_cb(lv_event_t *e) {
    lv_obj_t *btn = lv_event_get_target(e);
    char *ssid = (char*)lv_obj_get_user_data(btn);
    
    if (ssid) {
        strncpy(selected_wifi_ssid, ssid, sizeof(selected_wifi_ssid) - 1);
        selected_wifi_ssid[sizeof(selected_wifi_ssid) - 1] = '\0';
        show_wifi_password_modal();
    }
}

