static void wifi_connect_cb(lv_event_t *e) {
    LV_UNUSED(e);
    
    // 1. Get the pointer to the text
    const char *password = lv_textarea_get_text(wifi_password_ta);
    
    if (strlen(password) == 0) {
        show_toast("Please enter password", lv_color_hex(0xE74C3C), lv_color_white());
        return;
    }

    if (strlen(selected_wifi_ssid) == 0) {
        show_toast("No network selected", lv_color_hex(0xE74C3C), lv_color_white());
        return;
    }
    
    // 2. CRITICAL FIX: Setup config and copy strings NOW, while the text area still exists in memory
    wifi_config_t wifi_config = {0};
    strncpy((char*)wifi_config.sta.ssid, selected_wifi_ssid, sizeof(wifi_config.sta.ssid) - 1);
    strncpy((char*)wifi_config.sta.password, password, sizeof(wifi_config.sta.password) - 1);

    wifi_set_pending_credentials(
        selected_wifi_ssid,
        password
    );
    // wifi_config.sta.threshold.authmode = WIFI_AUTH_WPA2_PSK;
    wifi_config.sta.threshold.authmode = WIFI_AUTH_OPEN;
    
    // 3. Now it is safe to close and delete the modal
    if (wifi_password_modal) {
        lv_obj_del(wifi_password_modal);
        wifi_password_modal = NULL;
        wifi_password_ta = NULL;
        wifi_password_kb = NULL;
    }

    // 4. CRITICAL FIX: Disconnect to clear old state, but DO NOT use vTaskDelay or esp_wifi_stop
    esp_wifi_disconnect(); 
    
    esp_err_t ret = esp_wifi_set_config(WIFI_IF_STA, &wifi_config);
    if (ret != ESP_OK) {
        ESP_LOGE("WIFI", "Failed to set config: %s", esp_err_to_name(ret));
        show_toast("Connection failed!", lv_color_hex(0xE74C3C), lv_color_white());
        return;
    }
    
    ret = esp_wifi_connect();
    if (ret == ESP_OK) {
        // Because we removed the delays, this toast will render smoothly immediately!
        show_toast("Connecting...", lv_color_hex(0xF27330), lv_color_white());
    } else {
        show_toast("Connection failed!", lv_color_hex(0xE74C3C), lv_color_white());
    }
}

