static void show_wifi_password_modal(void) {
    if (wifi_password_modal != NULL) return;

    // 1. Full-screen dimmed backdrop overlay (prevents clicking behind it)
    wifi_password_modal = lv_obj_create(lv_scr_act());
    lv_obj_set_size(wifi_password_modal, LV_PCT(100), LV_PCT(100));
    lv_obj_set_style_bg_color(wifi_password_modal, lv_color_black(), 0);
    lv_obj_set_style_bg_opa(wifi_password_modal, LV_OPA_50, 0); 
    lv_obj_set_style_border_width(wifi_password_modal, 0, 0);
    lv_obj_set_style_pad_all(wifi_password_modal, 0, 0);
    lv_obj_clear_flag(wifi_password_modal, LV_OBJ_FLAG_SCROLLABLE);

    // 2. Floating Dialog Card Container (Matching email_card dimensions)
    lv_obj_t * wifi_card = lv_obj_create(wifi_password_modal);
    lv_obj_set_size(wifi_card, 440, 270);              
    lv_obj_center(wifi_card);                           
    lv_obj_set_style_bg_color(wifi_card, COLOR_CARD, 0);
    lv_obj_set_style_border_color(wifi_card, COLOR_ACCENT, 0);
    lv_obj_set_style_border_width(wifi_card, 2, 0);
    lv_obj_set_style_radius(wifi_card, 12, 0);          
    lv_obj_set_style_shadow_width(wifi_card, 24, 0);    
    lv_obj_set_style_shadow_opa(wifi_card, LV_OPA_40, 0);
    lv_obj_clear_flag(wifi_card, LV_OBJ_FLAG_SCROLLABLE);

    // 3. Instruction Label
    lv_obj_t * instruction = lv_label_create(wifi_card);
    lv_label_set_text(instruction, "Enter Wi-Fi Password:");
    lv_obj_set_style_text_color(instruction, COLOR_TEXT, 0);
    lv_obj_align(instruction, LV_ALIGN_TOP_LEFT, 5, 0);

    // 4. Text Area (Pinned to the top of the card so it stays visible)
    wifi_password_ta = lv_textarea_create(wifi_card);
    lv_textarea_set_one_line(wifi_password_ta, true);
    lv_textarea_set_password_mode(wifi_password_ta, true); // Hide characters as you type
    lv_obj_set_width(wifi_password_ta, 410);
    lv_obj_align(wifi_password_ta, LV_ALIGN_TOP_MID, 0, 28);

    // 5. Floating Virtual Keyboard (Matching email_kb size and placement)
    wifi_password_kb = lv_keyboard_create(wifi_card);
    lv_keyboard_set_mode(wifi_password_kb, LV_KEYBOARD_MODE_TEXT_LOWER); 
    lv_keyboard_set_textarea(wifi_password_kb, wifi_password_ta);
    lv_obj_set_size(wifi_password_kb, 410, 160);                 
    lv_obj_align(wifi_password_kb, LV_ALIGN_BOTTOM_MID, 0, 0);

    // Bind Keyboard Events (Hook these to your existing callbacks)
    lv_obj_add_event_cb(wifi_password_kb, wifi_connect_cb, LV_EVENT_READY, NULL);
    lv_obj_add_event_cb(wifi_password_kb, wifi_password_close_cb, LV_EVENT_CANCEL, NULL);
}

static void wifi_password_close_cb(lv_event_t *e) {
    LV_UNUSED(e);
    if (wifi_password_modal) {
        lv_obj_del(wifi_password_modal);
        wifi_password_modal = NULL;
        wifi_password_ta = NULL;
        wifi_password_kb = NULL;
    }
}

// ==========================================
// SECTION 3: ALERT EMAIL
// ==========================================
static void change_alert_email_cb(lv_event_t *e) {
    LV_UNUSED(e);
    
    time_t now;
    time(&now);
    
    if (email_verified && (now - email_change_timestamp) < (90 * 24 * 3600)) {
        uint32_t days_left = 90 - ((now - email_change_timestamp) / (24 * 3600));
        char msg[64];
        snprintf(msg, sizeof(msg), "Cannot change for %lu more days", (unsigned long)days_left);
        show_toast(msg, lv_color_hex(0xE74C3C), lv_color_white());
        return;
    }
    
    show_email_change_modal();
}

static void show_otp_modal(void) {
    if (otp_modal != NULL) {
        lv_obj_del(otp_modal);
    }
    
    otp_modal = lv_obj_create(lv_scr_act());
    lv_obj_set_size(otp_modal, 420, 250);
    lv_obj_center(otp_modal);
    lv_obj_set_style_bg_color(otp_modal, COLOR_CARD, 0);
    lv_obj_set_style_border_color(otp_modal, COLOR_ACCENT, 0);
    lv_obj_set_style_border_width(otp_modal, 2, 0);
    lv_obj_set_style_radius(otp_modal, 12, 0);
    
    // Close button (X)
    lv_obj_t *close_btn = lv_btn_create(otp_modal);
    lv_obj_set_size(close_btn, 28, 28);
    lv_obj_align(close_btn, LV_ALIGN_TOP_RIGHT, -5, 5);
    lv_obj_set_style_bg_opa(close_btn, LV_OPA_TRANSP, 0);
    lv_obj_set_style_shadow_width(close_btn, 0, 0);
    lv_obj_add_event_cb(close_btn, otp_close_cb, LV_EVENT_CLICKED, NULL);
    
    lv_obj_t *x_lbl = lv_label_create(close_btn);
    lv_label_set_text(x_lbl, LV_SYMBOL_CLOSE);
    lv_obj_set_style_text_color(x_lbl, COLOR_DIM, 0);
    lv_obj_center(x_lbl);
    
    // Title
    lv_obj_t *title = lv_label_create(otp_modal);
    lv_label_set_text(title, "Verify OTP");
    lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 10);
    
    // Info
    lv_obj_t *info = lv_label_create(otp_modal);
    lv_label_set_text_fmt(info, "OTP sent to %s", pending_alert_email);
    lv_obj_set_style_text_color(info, COLOR_DIM, 0);
    lv_obj_set_style_text_font(info, &lv_font_montserrat_10, 0);
    lv_obj_align(info, LV_ALIGN_TOP_MID, 0, 35);
    
    // OTP Input
    otp_ta = lv_textarea_create(otp_modal);
    lv_textarea_set_one_line(otp_ta, true);
    lv_textarea_set_max_length(otp_ta, 6);
    lv_textarea_set_placeholder_text(otp_ta, "Enter 6-digit OTP");
    lv_obj_set_width(otp_ta, 250);
    lv_obj_align(otp_ta, LV_ALIGN_TOP_MID, 0, 20);
    
    // Numpad (keyboard in number mode) - just like export email keyboard
    otp_kb = lv_keyboard_create(otp_modal);
    lv_keyboard_set_mode(otp_kb, LV_KEYBOARD_MODE_NUMBER);
    lv_keyboard_set_textarea(otp_kb, otp_ta);
    lv_obj_set_size(otp_kb, 370, 140);
    lv_obj_align(otp_kb, LV_ALIGN_BOTTOM_MID, 0, 0);
    
    // Keyboard events for Verify (READY) and Cancel
    lv_obj_add_event_cb(otp_kb, otp_kb_event_cb, LV_EVENT_READY, NULL);
    lv_obj_add_event_cb(otp_kb, otp_kb_event_cb, LV_EVENT_CANCEL, NULL);
}
static void otp_close_cb(lv_event_t *e) {
    LV_UNUSED(e);
    if (otp_modal) {
        lv_obj_del(otp_modal);
        otp_modal = NULL;
        otp_ta = NULL;
        otp_kb = NULL;
    }
}

static void otp_kb_event_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    
    if (code == LV_EVENT_READY) {
        const char *entered_otp = lv_textarea_get_text(otp_ta);
        
        if (strcmp(entered_otp, otp_code) == 0) {
            // OTP matches
            strncpy(alert_email, pending_alert_email, sizeof(alert_email) - 1);
            alert_email[sizeof(alert_email) - 1] = '\0';
            email_verified = true;
            time(&email_change_timestamp);

            /* ========================================================
            * PERSIST VERIFIED EMAIL
            * ======================================================== */

            if (!settings_save_alert_email(alert_email))
            {
                ESP_LOGE(
                    "SETTINGS",
                    "Failed to save alert email"
                );
            }

            if (!settings_save_email_verified(true))
            {
                ESP_LOGE(
                    "SETTINGS",
                    "Failed to save email verification state"
                );
            }

            if (!settings_save_email_change_timestamp(
                    (int64_t)email_change_timestamp))
            {
                ESP_LOGE(
                    "SETTINGS",
                    "Failed to save email change timestamp"
                );
            }
            
            if (alert_email_label) lv_label_set_text(alert_email_label, alert_email);
            if (alert_email_status) {
                lv_label_set_text(alert_email_status, LV_SYMBOL_OK " Verified");
                lv_obj_set_style_text_color(alert_email_status, COLOR_EXCELLENT, 0);
            }
            
            show_toast("Email verified successfully!", lv_color_hex(0x2ECC71), lv_color_white());
        } else {
            show_toast("Incorrect OTP, try again", lv_color_hex(0xE74C3C), lv_color_white());
        }
        
        // Close modal
        if (otp_modal) {
            lv_obj_del(otp_modal);
            otp_modal = NULL;
            otp_ta = NULL;
            otp_kb = NULL;
        }
    }
    else if (code == LV_EVENT_CANCEL) {
        if (otp_modal) {
            lv_obj_del(otp_modal);
            otp_modal = NULL;
            otp_ta = NULL;
            otp_kb = NULL;
        }
    }
}

static void send_otp_email(const char *recipient, const char *subject, const char *body) {
    if (!wifi_is_connected) {
        ESP_LOGW("SETTINGS", "WiFi not connected, cannot send OTP");
        return;
    }
    
    // char url[256];
    // snprintf(url, sizeof(url), 
    //          "https://script.google.com/macros/s/AKfycbxetIoethaNRiF_Qs_TuRoWBhKYCP3D8So3VXnraC5cPbinjEsLAACm9ICAGw4tJ49T/exec");

    // Use the Catalyst send-alert route for OTPs
    char url[256] = "https://project-rainfall-60082868759.development.catalystserverless.in/server/project_rainfall_function/api/send-report";
    
    // Send as JSON POST (not in URL)
    char payload[512];
    snprintf(payload, sizeof(payload), 
             "{\"recipient\":\"%s\",\"subject\":\"%s\",\"body\":\"%s\"}", 
             recipient, subject, body);
    
    esp_http_client_config_t config = {
        .url = url,
        .method = HTTP_METHOD_POST,
        .timeout_ms = 8000,
        .crt_bundle_attach = esp_crt_bundle_attach,
    };
    
    esp_http_client_handle_t client = esp_http_client_init(&config);
    if (client == NULL) {
        ESP_LOGE("SETTINGS", "Failed to create HTTP client");
        return;
    }
    
    esp_http_client_set_header(client, "Content-Type", "application/json");
    esp_http_client_set_post_field(client, payload, strlen(payload));
    
    esp_err_t err = esp_http_client_perform(client);
    
    if (err == ESP_OK) {
        int status = esp_http_client_get_status_code(client);
        ESP_LOGI("SETTINGS", "OTP sent, status: %d", status);
        show_toast("OTP sent to your email", lv_color_hex(0x2ECC71), lv_color_white());
    } else {
        ESP_LOGE("SETTINGS", "Failed to send OTP: %s", esp_err_to_name(err));
    }
    esp_http_client_cleanup(client);
}

static void settings_email_kb_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);

    if (code == LV_EVENT_READY) {
        const char *new_email = lv_textarea_get_text(settings_email_ta);
        
        if (new_email && strlen(new_email) > 5 && strchr(new_email, '@') && strchr(new_email, '.')) {
            // Save pending email and generate OTP
            strncpy(pending_alert_email, new_email, sizeof(pending_alert_email) - 1);
            
            // Generate random 6-digit OTP
            int otp = rand() % 900000 + 100000;
            snprintf(otp_code, sizeof(otp_code), "%06d", otp);
            
            ESP_LOGI("SETTINGS", "OTP for %s: %s", pending_alert_email, otp_code);

            // Send OTP via email using existing Google Script
            char otp_subject[64];
            char otp_body[256];
            snprintf(otp_subject, sizeof(otp_subject), "OPRUSS - Email Verification OTP");
            snprintf(otp_body, sizeof(otp_body), 
                    "Your OTP is: %s", otp_code);
            
            send_otp_email(pending_alert_email, otp_subject, otp_body);
        
            
            // Close email modal
            if (settings_email_modal) {
                lv_obj_del(settings_email_modal);
                settings_email_modal = NULL;
                settings_email_ta = NULL;
                settings_email_kb = NULL;
            }
            
            // Show OTP modal
            show_otp_modal();
        } else {
            show_toast("Please enter a valid email", lv_color_hex(0xE74C3C), lv_color_white());
            return;
        }
    } 
    else if (code == LV_EVENT_CANCEL) {
        if (settings_email_modal) {
            lv_obj_del(settings_email_modal);
            settings_email_modal = NULL;
            settings_email_ta = NULL;
            settings_email_kb = NULL;
        }
    }
}

