// --- Main Init After Splash ---
static void ui_init_main(void)
{
    current_screen_idx = 1;

    /* ========================================================
    * RESTORE SCREEN 3 STATE
    * ======================================================== */

    bool saved_screen3_live = true;
    int saved_screen3_range = 0;

    if (settings_load_screen3_state(
            &saved_screen3_live,
            &saved_screen3_range))
    {
        screen3_live_mode =
            saved_screen3_live;

        screen3_selected_range =
            saved_screen3_range;

        if (screen3_selected_range < 0 ||
            screen3_selected_range > 3)
        {
            screen3_selected_range = 0;
            screen3_live_mode = true;
        }
    }

    // Restore previously stored sleep state
    sleep_load_state();

    if (sleep_timer_active &&
        sleep_wake_epoch > 0)
    {
        sleep_schedule_set = true;
    }

    lv_obj_t *start_scr =
        build_screen_1();
    // lv_scr_load(start_scr);
    // Replace instant lv_scr_load with a smooth 500ms fade animation
    lv_scr_load_anim(start_scr, LV_SCR_LOAD_ANIM_FADE_OUT, 250, 0, true);
    
    lv_timer_create(main_data_timer_cb, 1000, NULL);
    if (sleep_timer_active &&
        sleep_wake_epoch > 0) {

        time_t now;
        time(&now);

        if ((uint64_t)now >= sleep_wake_epoch) {

            sleep_timer_active = false;
            sleep_wake_epoch = 0;

            aq7_sensing_enabled = true;

            sleep_save_state();

        } else {

            sleep_start_off_state();

            if (!sleep_countdown_timer) {
                sleep_countdown_timer =
                    lv_timer_create(
                        sleep_countdown_cb,
                        1000,
                        NULL
                    );
            }
        }
    }
}

// --- Public Init Function ---
void ui_init(void) {
    // ui_data.pm10 = -1.0f;
    real_data.pm10 = -1.0f;
    purifier_load_state();
    // This prevents the white flash before the splash screen is fully rendered.
    lv_obj_set_style_bg_color(lv_scr_act(), COLOR_BG, 0);
    current_screen_idx = 0; 
    lv_obj_t * splash_scr = build_splash_screen();
    lv_scr_load(splash_scr);
}

void ui_push_sensor_data(sensor_data_t *incoming)
{
    if(incoming == NULL)
        return;

    ESP_LOGI(
        "SENSOR_RX",
        "INCOMING BEFORE COPY: "
        "AQI=%d PM25=%.2f PM10=%.2f "
        "TVOC=%.2f TEMP=%.2f HUM=%.2f",

        incoming->aqi,
        (double)incoming->pm25,
        (double)incoming->pm10,
        (double)incoming->tvoc,
        (double)incoming->temp,
        (double)incoming->humidity
    );

    if (xSemaphoreTake(sensor_mutex, pdMS_TO_TICKS(100)) == pdTRUE)
    {
        real_data = *incoming;

        /*
        * A real sensor packet has now been received.
        *
        * This flag is independent of the numerical values.
        *
        * Therefore:
        *
        * AQI=0 does NOT mean "sensor disconnected".
        * AQI=0 with this flag set means the sensor actually
        * reported AQI=0.
        */
        sensor_data_received = true;

        /*
        * Normalize the actual received measurements.
        *
        * This stays in RAM.
        * Nothing is written to SD card.
        */
        if (air_quality_normalize(
                real_data.pm25,
                real_data.pm10,
                real_data.tvoc,
                real_data.temp,
                real_data.humidity,
                real_data.aqi,
                &normalized_air_data))
        {
            /*
            * CAQI is calculated only when the required
            * normalized parameters are available.
            */
            if (!air_quality_calculate_caqi(
                    &normalized_air_data,
                    &current_caqi))
            {
                current_caqi = -1.0f;
            }
        }
        else
        {
            normalized_air_data.valid = false;
            current_caqi = -1.0f;
        }



        // if (fan_controller_get_mode() == FAN_MODE_AUTO)
        // {
        //     fan_controller_update_auto(
        //         current_caqi
        //     );
        // }

        if (fan_controller_get_mode() == FAN_MODE_AUTO)
        {
            // Pass all normalized weights to the new dual-fan math engine
            fan_controller_update_auto(
                normalized_air_data.pm25_n,
                normalized_air_data.pm10_n,
                normalized_air_data.tvoc_n,
                normalized_air_data.temp_n,
                normalized_air_data.humidity_n
            );
        }

         /* ========================================================
        * TEMPORARY DEBUG LOG
        * ======================================================== */

        ESP_LOGI(
            "AIR_MODEL",
            "NORMALIZED: "
            "PM25_N=%.3f "
            "PM10_N=%.3f "
            "TVOC_N=%.3f "
            "T_N=%.3f "
            "RH_N=%.3f "
            "AQI_N=%.3f "
            "CAQI=%.3f",

            (double)normalized_air_data.pm25_n,
            (double)normalized_air_data.pm10_n,
            (double)normalized_air_data.tvoc_n,
            (double)normalized_air_data.temp_n,
            (double)normalized_air_data.humidity_n,
            (double)normalized_air_data.aqi_n,
            (double)current_caqi
        );
        

        xSemaphoreGive(sensor_mutex);

        static int64_t last_snapshot_save_us = 0;

        int64_t now_us =
            esp_timer_get_time();

        if (
            last_snapshot_save_us == 0 ||
            (now_us - last_snapshot_save_us) >=
                (60LL * 1000000LL)
        )
        {
            settings_sensor_snapshot_t snapshot;

            snapshot.aqi =
                incoming->aqi;

            snapshot.pm25 =
                incoming->pm25;

            snapshot.pm10 =
                incoming->pm10;

            snapshot.tvoc =
                incoming->tvoc;

            snapshot.temp =
                incoming->temp;

            snapshot.humidity =
                incoming->humidity;

            snapshot.pressure =
                incoming->pressure;

            snapshot.eco2 =
                incoming->eco2;

            snapshot.fan_speed =
                incoming->fan_speed;

            snapshot.filter_life =
                incoming->filter_life;


            if (settings_save_sensor_snapshot(
                    &snapshot))
            {
                last_snapshot_save_us =
                    now_us;

                ESP_LOGI(
                    "NVS",
                    "Sensor snapshot saved"
                );
            }
            else
            {
                ESP_LOGE(
                    "NVS",
                    "Failed to save sensor snapshot"
                );
            }
        }

        ESP_LOGI(
            "SENSOR_RX",
            "REAL_DATA AFTER COPY: "
            "AQI=%d PM25=%.2f PM10=%.2f "
            "TVOC=%.2f TEMP=%.2f HUM=%.2f",

            real_data.aqi,
            (double)real_data.pm25,
            (double)real_data.pm10,
            (double)real_data.tvoc,
            (double)real_data.temp,
            (double)real_data.humidity
        );
    }
    else
    {
        ESP_LOGW(
            "SENSOR_RX",
            "Could not acquire sensor_mutex"
        );
    }

    

    if (aqi_val_lbl != NULL)
    {
        lv_label_set_text_fmt(
            aqi_val_lbl,
            "%d",
            real_data.aqi
        );
    }
}

bool ui_has_sensor_data(void)
{
    bool received = false;

    if (xSemaphoreTake(sensor_mutex, pdMS_TO_TICKS(100)) == pdTRUE)
    {
        received = sensor_data_received;

        xSemaphoreGive(sensor_mutex);
    }

    return received;
}

bool ui_get_normalized_air_data(
    normalized_air_data_t *out)
{
    if (out == NULL)
        return false;

    if (!sensor_data_received)
        return false;

    if (xSemaphoreTake(
            sensor_mutex,
            pdMS_TO_TICKS(100)) != pdTRUE)
    {
        return false;
    }

    *out = normalized_air_data;

    xSemaphoreGive(sensor_mutex);

    return out->valid;
}

bool ui_get_caqi(float *caqi)
{
    if (caqi == NULL)
        return false;

    if (!sensor_data_received)
        return false;

    if (current_caqi < 0.0f)
        return false;

    if (xSemaphoreTake(
            sensor_mutex,
            pdMS_TO_TICKS(100)) != pdTRUE)
    {
        return false;
    }

    *caqi = current_caqi;

    xSemaphoreGive(sensor_mutex);

    return true;
}

